var fs = global.get('fs');
var path = global.get('path');
var commonLib = global.get('commonLib');
var setting = commonLib.getSettings();
var xml = global.get('report_xml');

/**
 * 複数ファイルかどうかを判定する関数です。
 * @param {*} msg 
 * @returns 
 */
function isMultipleFile(msg) {
    return msg.multiResults && msg.multiResults.length > 1;
}

/**
 * コピー／リネームを含むファイル送信処理を行う。
 * @param {*} msg 
 * @returns 
 */
function processingFile(msg) {
    var protocol = msg.payload.protocolInfo.protocol;

    var fileSource;
    var fileDestPath;
    var fileDest;
    var indicator = '/';

    // mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 start
    // 検査用電文種別
    var checkCoopCd = msg.payload.journalInfo.coop_version + '#~#' + msg.payload.journalInfo.coop_cd + '#~#' + msg.payload.journalInfo.coop_cd_index;
    // mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 end

    // テンポラリファイル
    fileSource = msg.filename;
    // ファイル名
    var filename = msg.orgFilename;
    if (msg.payload.protocolInfo.dummy === 'true') {
        // mod 2022-11-02 bug #8028 応答待ちのジャーナルがあると、送信処理が実施されない 孫 start
        //    fileSource = commonLib.createDummyFile(setting.tmpDirPath);
        try {
            fileSource = commonLib.createDummyFile(setting.tmpDirPath);
        } catch (err) {
            node.error(err, msg);
            msg.loglevel = "error";

            // 接続失敗
            // 配信停止の電文種別がない場合、追加する
            if ((global.get('stopCoopList')).indexOf(checkCoopCd) === -1) {
                (global.get('stopCoopList')).push(checkCoopCd);
            }
            msg.N_status = "init";
            msg.N_message = '送信時に接続に失敗しました。 [' + err.stack + '] 配信設定[' + JSON.stringify(msg.payload.protocolInfo) + ']';

            node.send(msg);
            return;
        }
        // mod 2022-11-02 bug #8028 応答待ちのジャーナルがあると、送信処理が実施されない 孫 end
    }

    fileDestPath = msg.payload.protocolInfo.address;
    fileDest = fileDestPath + indicator + filename;

    var targetPath = fileDest;

    fileDest = fileDestPath + indicator + msg.payload.protocolInfo.renameWhenCopying + filename;

    try {
        // if the directory does not exist, create it.
        commonLib.createDirectory(fileDestPath);
    } catch (err) {
        node.error(err, msg);
        msg.loglevel = "error";
        msg.N_status = "error";
        msg.N_message = "IFEdge:File copy failed [" + err.stack + "]";

        // mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 start
        // 接続失敗
        // 配信停止の電文種別がないの場合、追加する
        if ((global.get('stopCoopList')).indexOf(checkCoopCd) === -1) {
            (global.get('stopCoopList')).push(checkCoopCd);
        }
        // 接続Statusを再設定する。
        msg.N_status = "init";
        msg.N_message = '送信時に接続に失敗しました。 [' + err.stack + '] 配信設定[' + JSON.stringify(msg.payload.protocolInfo) + ']';
        // mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 end

        node.send(msg);
        return;
    }
    //console.log('SMB-copy---------3 -->');

    // mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 start
    let stopIndex = (global.get('stopCoopList')).indexOf(checkCoopCd);
    if (stopIndex !== -1) {
        // 接続成功、配信停止の電文種別がありの場合、削除する
        (global.get('stopCoopList')).splice(stopIndex, 1);
    }
    // mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 end

    try {

        // 処理を移動する
        //    // if the directory does not exist, create it.
        //    commonLib.createDirectory(fileDestPath);

        if (msg.payload.protocolInfo.replace === 'report_merge') {
            if (xml.isReportXml(filename)) {
                xml.createOrReplaceReportXml(filename, fileDest, fileSource);
            } else {
                fs.copyFileSync(fileSource, fileDest);
            }
        } else {
            fs.copyFileSync(fileSource, fileDest);
        }
    } catch (err) {
        node.error(err, msg);
        msg.loglevel = "error";

        // 接続失敗
        // 配信停止の電文種別がない場合、追加する
        if ((global.get('stopCoopList')).indexOf(checkCoopCd) === -1) {
            (global.get('stopCoopList')).push(checkCoopCd);
        }
        msg.N_status = "init";
        msg.N_message = '送信時に接続に失敗しました。 [' + err.stack + '] 配信設定[' + JSON.stringify(msg.payload.protocolInfo) + ']';

        node.send(msg);
        return;
    }

    if (msg.payload.protocolInfo.renameWhenCopying !== "") {
        // 指定あり
        try {
            fs.renameSync(fileDest, targetPath);
        } catch (err) {
            node.error(err, msg);
            msg.loglevel = "error";

            // 接続失敗
            // 配信停止の電文種別がない場合、追加する
            if ((global.get('stopCoopList')).indexOf(checkCoopCd) === -1) {
                (global.get('stopCoopList')).push(checkCoopCd);
            }
            msg.N_status = "init";
            msg.N_message = '送信時に接続に失敗しました。 [' + err.stack + '] 配信設定[' + JSON.stringify(msg.payload.protocolInfo) + ']';

            node.send(msg);
            return;
        }
    }

    msg.loglevel = "info";
    msg.N_status = "success";
    msg.N_message = "File copy success [" + fileSource + "] => [" + targetPath + "]";

    return msg;
}



/**
 * 複数ファイルの処理を行う関数です。
 * msg.multiResults の各メッセージに対して単一ファイル処理を実行します。
 * @param {*} msg 
 * @returns 
 */
function processingMultipleFiles(msg) {
    const processedResults = [];
    for (const singleMsg of msg.multiResults) {
        try {
            // 既存処理の変更をしたくないためこのように実装
            singleMsg.payload.protocolInfo.address = path.join(singleMsg.payload.protocolInfo.address, singleMsg.payload.data.dirPath);
            const result = processingFile(singleMsg);
            processedResults.push(result);
        } catch (error) {
            node.error(`ファイル処理中にエラーが発生しました: ${error.message}`, singleMsg);
            processedResults.push(singleMsg);
            msg.multiResults = processedResults;
            msg.loglevel = "error";
            msg.N_status = "init";
            msg.N_message = `ファイル送信処理に失敗しました: [${singleMsg.orgFilename}]`;
            return msg; // エラーが発生した場合はここで終了
        }
    }
    msg.multiResults = processedResults;
    msg.loglevel = "info";
    msg.N_status = "success";
    node.log(`複数ファイルの送信処理に成功しました: ${processedResults.length} ファイルが処理されました。`);
    return msg;
}

/**
 * 単一ファイルの処理を行う関数です。
 * @param {*} msg 
 * @returns 
 */
function processingSingleFile(msg) {
    const singleMsg = JSON.parse(JSON.stringify(msg));
    if (singleMsg.payload.data.dirPath) {
        singleMsg.payload.protocolInfo.address = path.join(singleMsg.payload.protocolInfo.address, singleMsg.payload.data.dirPath);
    }
    const result = processingFile(singleMsg);
    return result;
}

// 実行分岐ロジック
let resultMsg = isMultipleFile(msg) ? processingMultipleFiles(msg) : processingSingleFile(msg);

return resultMsg;

