    msg.socketFalg = 'Cli_Snd_Retry_' + currRetryTime + '_TimeOut_' + currRetryCount;
    node.send([null, null, null, msg]);
});

var ALL_data;
var ALL_length = -1;
var currentData;

client.on("data", function (data) {
    node.warn("★client.on.data");
    // 今回受信したデータを保存
    currentData = data;
    node.warn("★client.on.currentData" + currentData);
    if (!ballInCourt) {
        // コンソールに表示
        //node.log('Socket Data Length [' + data.length+ '] Received message [' + commonLib.decodeBuffer(data, 'shift-jis').replace(/\r/g, ' ') + ']');
        // 受信データのLengthを取得する
        if (ALL_length == -1) {
            ALL_length = socketlib.getLength(socketType, data);
            ALL_data = data;
            //console.log('★★★first ALL_length : [' + ALL_length + ']');
            //console.log('★★★first [' + ALL_data.length + '] ALL_data : [' + commonLib.decodeBuffer(ALL_data, 'shift-jis').replace(/\r/g, ' ') + ']');
        } else {
            ALL_data = Buffer.concat([ALL_data, data]);
            //console.log('★★★next [' + ALL_data.length + '] ALL_data : [' + commonLib.decodeBuffer(ALL_data, 'shift-jis').replace(/\r/g, ' ') + ']');
        }

        // 受信データのLengthをチェックする
        //console.log('★★★ALL_data.length  [' + ALL_data.length + '] ALL_length : [' + ALL_length + ']');
        if (ALL_length !== 0 && ALL_data.length < ALL_length) {
            return;
        }

        // dataにデータを再設定する
        data = Buffer.alloc(ALL_data.length);
        ALL_data.copy(data, 0, 0, ALL_data.length);
        node.log('=========>Received message [' + commonLib.decodeBuffer(data, 'shift-jis').replace(/\r/g, ' ') + ']');

        // #5293:[送信時：再送信時の動きについて]
        // Save Receive Data
        msg.scoketData = data;
        msg.socketFalg = 'Cli_Rev_Retry_' + currRetryTime + '_TimeOut_' + currRetryCount;
        node.send([null, null, null, msg]);

        // 【追加】request電文の再送＆validation処理
        if (request && socketType == 'pana') {
            // NAKが来たら再送
            var isRetry = socketlib.isRetry(socketType, currentData);
            if (isRetry) {
                // 最大回数チェック
                if (runValidation("retrycountOver", currentData, socketType, msg)) {
                    node.warn("★retrycountOver")
                    // ACKの受信待ち開始
                    startErrorAckTimer();
                    return;
                }

                // 要求電文を再送
                client.write(sendData);
                ballInCourt = false;

                // Save Send data
                msg.scoketData = sendData;
                msg.socketFalg = 'Cli_Snd_Retry_' + currRetryTime + '_TimeOut_' + currRetryCount;
                node.send([null, null, null, msg]);
                return;
            }
            // TODO エラー電文ACK待ち状態でACKが来たか(NAK以外で)（動確まだです）
            if (waitingForErrorAck && !isRetry) {
                // TODO ACK判定、設定足して固定値のほうがよいかも
                if (currentData[0] === 0x06) {
                    clearTimeout(errorAckTimer);
                    waitingForErrorAck = false;
                    node.warn("★エラー電文に対するACKを受信しました");
                } else {
                    clearTimeout(errorAckTimer);
                    waitingForErrorAck = false;
                    node.warn("★★エラー電文に対する応答電文をACK以外で受信しました");
                }
                //切断電文送信
                createRequestResponse["disconnect"]();
                node.warn("★ACK,切断電文送信しました");
                //切断電文ACKタイマーセット
                startDisconnectAckTimer();
                return;
            }
            // TODO 切断電文ACK待ち状態でACKが来たか（動確まだです）
            if (waitingForDisconnectAck) {
                // TODO ACK判定、設定足して固定値のほうがよいかも
                node.warn("★data[0]: " + currentData[0]);
                if (currentData[0] === 0x06) {
                    clearTimeout(disconnectAckTimer);
                    waitingForDisconnectAck = false;
                    node.warn("★切断要求に対するACKを受信しました");
                } else {
                    clearTimeout(disconnectAckTimer);
                    waitingForDisconnectAck = false;
                    node.warn("★切断要求に対する応答電文をACK以外で受信しました");
                }
                client.destroy();
                return;
            }
            //ACK待ちでなければバリデージョンして電文送る
            const shouldDestroy =
                (runValidation("dataLengthCheck", currentData, socketType, msg)) ||
                (runValidation("matchCheck", currentData, socketType, msg)) ||
                (runValidation("existsCheck", currentData, socketType, msg));

            //バリデージョン引っかかってたらエラー電文を送った後にACK待ちをするので、timerをつける
            if (shouldDestroy) {
                node.warn("★validation引っかかった")
                // ACKの受信待ち開始
                startErrorAckTimer();
                return;
            }
            node.warn("★validation通過");
            createRequestResponse["ack"]();
            //通常ACK送信後切断電文送信？
            createRequestResponse["disconnect"]();
            node.warn("★ACK,切断電文送信しました");
            //切断電文ACKタイマーセット
            startDisconnectAckTimer();
            setStatus('normal', 'normal');
            msg.requestData = currentData;
            node.send([msg, null, null, null]);
            // request処理のon.data内追加ぶんここまで TODOおわり
        } else {
            // 電文長がOK？
            if (socketlib.checkValidation(socketType, data, 1, 'type')) {
                client.destroy();
                setStatus('normal', 'normal');
                msg.requestData = data;
                node.send([msg, null, null, null]);
            } else {
                // エラーリターン
                client.destroy();
                setStatus('error', 'IFEdge:電文長不正.');
                node.send([null, msg, null, null]);
            }
        }
    } else {
        console.log('ボール持ってるのに来た');
    }
});

client.on("close", function () {
    node.warn("★client.on.close");
    client.destroy();
    console.log('===========>close client host[' + host + '] port[' + port + ']');
});

client.on("error", function (err) {
    node.warn("★client.on.error");
    node.warn("★ConnectionSucc:" + ConnectionSucc);
    client.destroy();
    setStatus('error', 'IFEdge:ソケットエラー.' + err);

    //console.log('TCP-Client---------in error ConnectionSucc -->[' + ConnectionSucc + ']');
    // mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 start
    // 接続失敗
    if (ConnectionSucc === false) {
        // 配信停止の電文種別がないの場合、追加する
        if ((global.get('stopCoopList')).indexOf(checkCoopCd) === -1) {
            (global.get('stopCoopList')).push(checkCoopCd);
        }
        // 接続Statusを再設定する。
        setStatus('init', '送信時に接続に失敗しました。配信設定[' + JSON.stringify(msgInfo.protocolInfo) + ']');
    }
    // mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 end
    node.send([null, msg, null, null]);
});

client.on('timeout', function () {
    node.warn("★timeoutnow");
    if (ALL_data !== undefined && ALL_data.length > 0) {
        // Save Receive Data
        msg.scoketData = ALL_data;
        msg.socketFalg = 'Cli_Rev_Retry_' + currRetryTime + '_TimeOut_' + currRetryCount;
        node.send([null, null, null, msg]);
    }
    //【追加】タイムアウト → ACK待ち用タイマーの起動
    if (request && socketType == 'pana') {
        node.warn("★timeoutHandled:" + timeoutHandled);
        if (timeoutHandled) {
            node.warn("★returnする")
            clearTimeout(disconnectAckTimer);
            return;
        } //複数回処理しないようブロックする
        try {
            timeoutHandled = true;
            // タイムアウト電文の送信
            const defaultValidations = getValidations(socketType, "timeout");
            const defaultValidation = defaultValidations[0] || {
                error_message: "ソケットの受信タイムアウトが発生しました",
                error_code: "00010"
            };
            setStatus('error', defaultValidation.error_message);
            createRequestResponse["error"](defaultValidation.error_code);
            node.send([null, msg, null, null]);

            // ACKの受信待ち
            startErrorAckTimer();
            return;
        }
        catch (e) {
            node.warn("送信失敗" + e);
            const defaultValidations = getValidations(socketType, "unexpectedError");
            const defaultValidation = defaultValidations[0] || {
                error_message: "例外が発生しました",
                error_code: "99999"
            };
            setStatus('error', defaultValidation.error_message);
            createRequestResponse["error"](defaultValidation.error_code);
            node.send([null, msg, null, null]);

            return;
        }
    }
    client.destroy();
    setStatus('timeout', 'IFEdge:応答電文のタイムアウト.時間[' + timeout / 1000 + ']秒.');
    node.send([null, null, msg, null]);
});

var getValidations = function (socketType, check_type) {
    // 応答電文の設定を取得する
    const responseTelegram = socketlib.getResponseTelegram(socketType);
    if (!responseTelegram) {
        return [];
    }
    // 正常応答電文の設定を取得する
    const validations = responseTelegram.validations;
    if (!Array.isArray(validations)) {
        return [];
    }

    let result = new Set();
    for (var i = 0; i < validations.length; i++) {
        if (validations[i].check_type === check_type) {
            result.add(validations[i]);
        }
    }
    return result;
};

function runValidation(type, data, socketType, msg) {
    const validations = getValidations(socketType, type);
    for (const validation of validations) {
        try {
            const result = checkValidate(data, validation);
            if (result) {
                const { error_message, error_code } = result;
                setStatus('error', error_message);
                createRequestResponse["error"](error_code);                
                node.send([null, msg, null, null]);

                msg.scoketData = sendData;
                msg.socketFalg = 'Cli_Snd_Retry_' + currRetryTime + '_TimeOut_' + currRetryCount;
                node.send([null, null, null, msg]);

                return true; // 終了
            }
        }
        catch (e) {
            const defaultValidations = getValidations(socketType, "unexpectedError");
            const defaultValidation = defaultValidations[0] || {
                error_message: "例外が発生しました",
                error_code: "99999"
            };
            setStatus('error', defaultValidation.error_message);
            createRequestResponse["error"](defaultValidation.error_code);            
            node.send([null, msg, null, null]);

            msg.scoketData = sendData;
            msg.socketFalg = 'Cli_Snd_Retry_' + currRetryTime + '_TimeOut_' + currRetryCount;
            node.send([null, null, null, msg]);

            return true;
        }
    }
    return false; // Validation = OK
}

//【追加】バリデージョン
var checkValidate = function (buf, validate) {
    //【追加】一致チェック
    if (validate.check_type == "matchCheck") {
        var header = commonLib.Str2Hex(validate.header);
        if (header != (buf[0])) {
            return null;
        }

        var start = parseInt(validate.start, 10);
        var end = parseInt(validate.end, 10);

        if (validate.is_error_only && buf[0] !== 0x10) {
            return null; // 通常電文時なのに見ようとしている箇所がis_error_onlyであればスキップ
        }

        var decision_values = validate.decision_values;
        if (typeof decision_values === 'string') {
            decision_values = decision_values.split(',');  // 例："MDT0,MDD0" → ["MDT0", "MDD0"]
        }

        let data = buf.slice(start, end);
        const charCode = data[0];

        let dataStr;
        if (charCode < 0x20 || charCode === 0x7F) {
            dataStr = '0x' + charCode.toString(16).padStart(2, '0');
        }
        else {
            dataStr = data.toString();
        }

        if (!decision_values.includes(dataStr)) {
            return {
                error_message: validate.error_message,
                error_code: validate.error_code
            }
        }

        return null;
    }
    //【追加】存在チェック
    if (validate.check_type == "existsCheck") {
        var header = commonLib.Str2Hex(validate.header);
        if (header != (buf[0])) {
            return null;
        }

        var startValue = parseInt(validate.start_value, 16);
        var targeValue = parseInt(validate.targe_value, 16);
        var isExists = validate.is_exists;
        let data = buf.slice(1);

        if (buf[0] != startValue) {
            return null;
        }

        if (isExists) {
            if (!data.includes(targeValue)) {
                return {
                    error_message: validate.error_message,
                    error_code: validate.error_code
                }
            }
        } else {
            if (data.includes(targeValue)) {
                return {
                    error_message: validate.error_message,
                    error_code: validate.error_code
                }
            }
        }
    }
    //【追加】電文長一致
    if (validate.check_type == "dataLengthCheck") {
        var header = commonLib.Str2Hex(validate.header);
        var dataLength = validate.data_length;
        if (header != (buf[0])) {
            return null;
        }
        if (buf.length != dataLength) {
            return {
                error_message: validate.error_message,
                error_code: validate.error_code
            }
        }
    }
    //【追加】再送要求回数超過
    if (validate.check_type == "retrycountOver") {
        if (msg.currRetryCount > retryMax) {
            //最大
            return {
                error_message: validate.error_message,
                error_code: validate.error_code
            }
        }
        msg.currRetryCount += 1;
    }
    return null;
};

//【追加】来た電文に対する応答用の電文作成
var createRequestResponse = {
    // request電文への応答
    ack: function () {
        node.warn("★ACK応答");
        const ackCode = parseInt("0x06", 16);
        client.write(Buffer.from([ackCode]));
    }
    // request電文へのエラー応答
    , error: function (error_code) {
        node.warn("★エラー応答 エラーコード:" + error_code);
        const telegramConfig = socketlib.getResponseTelegram(socketType);
        const failureHeader = telegramConfig.response_failure.header;

        const updatedHeader = failureHeader.map(field => {
            if (field.name === "ErrorCode") {
                return {
                    ...field,
                    value: error_code
                };
            }
            return field;
        });

        const bufferParts = updatedHeader.map(field => {
            if (field.value?.toString().startsWith("0x")) {
                //16進数の変換
                return Buffer.from([parseInt(field.value, 16)]);
            } else {
                return Buffer.from(field.value);
            }
        });
        const errorBuf = Buffer.concat(bufferParts);
        client.write(errorBuf);
        sendData = errorBuf;
    }
    // 切断電文応答
    , disconnect: function () {
        const telegramConfig = socketlib.getResponseTelegram(socketType);
        const failureHeader = telegramConfig.response_disconnect.header;

        const bufferParts = failureHeader.map(field => {
            if (field.value?.toString().startsWith("0x")) {
                //16進数の変換
                return Buffer.from([parseInt(field.value, 16)]);
            } else {
                return Buffer.from(field.value);
            }
        });
        const disconnectBuf = Buffer.concat(bufferParts);
        client.write(disconnectBuf);
    }
};

//【追加】ACK待ち用タイマー
function startErrorAckTimer() {
    waitingForErrorAck = true;

    errorAckTimer = setTimeout(() => {
        if (waitingForErrorAck) {
            node.warn("エラー電文に対する応答電文の受信に失敗しました");
            clearTimeout(errorAckTimer);
            createRequestResponse["disconnect"]();
            startDisconnectAckTimer();
            node.warn("★ACK,切断電文送信しました");
            return;
        }
    }, timeout);
}

//【追加】ACK待ち用タイマー
function startDisconnectAckTimer() {
    waitingForDisconnectAck = true;

    disconnectAckTimer = setTimeout(() => {
        if (waitingForDisconnectAck) {
            node.warn("切断要求に対する応答電文の受信に失敗しました");
            client.destroy();
            clearTimeout(disconnectAckTimer);
            return;
        }
    }, timeout);
}


return;

function setStatus(stat, message) {
    msg.N_status = stat;
    msg.N_message = message;
}

