            tshOneData.TotalCounter = commonLib.LeftAppend(util.format('%d', dataCnt), len, '0');;
        }
        // 最終データか？
        var body_length = 0;
        if (i === (totalCnt-2)) {
            body_length = (orgData.length - (i - 1) * tshformat.data_max_length);
            tshOneData.ContinuationFlag = '0';
        } else {
            body_length = tshformat.data_max_length;
            tshOneData.ContinuationFlag = '1';
        }
        var dataLength = tshformat.header_length + body_length;
        let len = tshOneData.TelegramLength.length;
        tshOneData.TelegramLength = commonLib.LeftAppend(util.format('%d', dataLength), len, '0');
        var start = (i - 1) * tshformat.data_max_length;
        tshOneData.Data = orgData.slice(start, start + dataLength);
//node.log('>>>>>>>>>> tshOneData.Data['+i+']=[' + commonLib.decodeBuffer(tshOneData.Data, 'shift-jis') + ']');
    }
    tshData[i] = Buffer.alloc((tshOneData.TelegramLength)*1);
    var begin = 0;
    for (let key in tshOneData) {
        if (key === 'Data' ) {
//node.log('>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>' + ('                   ' + key).substr(-20) + ' begin=['+ begin +'] length=['+ tshOneData[key].length +']');
            if (tshOneData[key].length > 0) {
