                var decodeTmp = commonLib.decodeBuffer(tshOneData[key], 'shift-jis');
                (commonLib.encodeString(decodeTmp, 'shift-jis')).copy(tshData[i], begin, 0, tshOneData[key].length);
                begin = begin + tshOneData[key].length;
