        } else {
            if (tshOneData[key].startsWith('0x') || tshOneData[key].startsWith('0X')) {
//node.log('>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>' + ('                   ' + key).substr(-20) + ' begin=['+ begin +'] length=['+ tshOneData[key].length +']');
                // 2進数の場合、Unicodeコードを1文字に変換する
//node.log('>>>>>>>>>> Before tshData['+i+']=['+ Bytes2HexString(tshData[i]) +']');
                (commonLib.encodeString(String.fromCharCode(commonLib.Str2Hex(tshOneData[key])), 'shift-jis')).copy(tshData[i], begin, 0, 1);
                begin = begin + 1;
//node.log('>>>>>>>>>> After  tshData['+i+']=['+ Bytes2HexString(tshData[i]) +']');
            } else {
