function Bytes2HexString(retBuf) {
    let hexs = "";
    for (var k = 0; k < retBuf.length; k++) {
        let hex = (retBuf[k]).toString(16);
        if (hex.length === 1) {
            hexs = hexs + '0';
        }
        hexs = hexs + hex.toUpperCase() + ' ';
    }
    return hexs;
}

