        setStatus('error','tshplus_format error: format[' + (i+1) + '].length undefined.');
        node.send([msg, null]);
        return;
    }
    // check value undefined
    if (format.value === undefined) {
        setStatus('error','tshplus_format error: format[' + (i+1) + '].value undefined.');
        node.send([msg, null]);
        return;
    }
    // check length = 0 ?
    if (format.name !== 'Data' && format.length === 0) {
        setStatus('error','tshplus_format error: format[' + (i+1) + '].length = 0.');
        node.send([msg, null]);
        return;
    }
    // check value = '' ?
    if (format.name !== 'Data' && format.value.length === 0) {
        setStatus('error','tshplus_format error: format[' + (i+1) + '].value = null.');
        node.send([msg, null]);
        return;
    }
    // check value.length = length ?
    if (format.name !== 'Data') {
        if ((format.value.startsWith('0x') === false && format.value.length !== format.length) 
         || (format.value.startsWith('0x') === true  && format.length !== 1)) {
            setStatus('error','tshplus_format error: format[' + (i+1) + '].value.length <> length.');
            node.send([msg, null]);
            return;
        }
    } else {
        if (format.value.length !== 0 || format.length !== 0) {
            setStatus('error','tshplus_format error: format[' + (i+1) + '].value.length <> length.');
            node.send([msg, null]);
            return;
        }
    }
}

