var retryInterval = 10 * 1000;
if (msg.messageInfo.protocolInfo.retryInterval !== undefined && msg.messageInfo.protocolInfo.retryInterval > 0) {
    retryInterval = msg.messageInfo.protocolInfo.retryInterval * 1000;
}

//  リトライ最大数
var retryMax = msg.messageInfo.protocolInfo.retryMax;
var request = msg.messageInfo.protocolInfo.sendType === 'request' ? true : false;
var dataType = msg.messageInfo.journalInfo.coop_cd;

var retryCount = msg.retryCount; 

var stat =  msg.N_status;
var message = msg.N_message;

if (stat === 'timeout') {
    // 東芝医療連携：クライアントでタイムアウトしたとき場合、再接続、送信側はデータの再送を試みる
    if (socketType === 'TOSHIBA_TSHPlus') {
        if (retryCount < retryMax) {
            ++retryCount;
            msg.retryCount = retryCount;
            node.send([null, null, null, null, null, msg]);
            return;
        }
    }
    node.send([null, null, msg, null, null, null]);

    // #5261:TSHPlusにおけるデータのジャーナル反映について.
    SendErrorRequestDate();
    return;
} else if (stat === 'error' || stat === 'init') {
    node.send([null, msg, null, null, null, null]);

    // #5261:TSHPlusにおけるデータのジャーナル反映について.
    SendErrorRequestDate();
    return;
} else if (stat === 'continue') {
    // NEC連携:受信側でエラーを検出したとき(セッション切断依頼)、再接続、送信側はデータの再送を試みる
    if (socketType === 'NEC_TSHPlus' || socketType === 'NEC_TSHMedicine' ) {
    	if(retryCount + 1 < retryMax ) {
	        // NEC連携：クライアントでタイムアウトしたとき場合、再接続、送信側はデータの再送を試みる
	        ++retryCount;
	        msg.retryCount = retryCount;
	        await sleep(retryInterval);
	        node.send([null, null, null, null, null, msg]);
	        return;
	    } else {
	        setStatus('timeout', 'IFEdge:TSH リトライ最大回数[' + (retryCount + 1) + ']に達しました.');
	        node.send([null, null, msg, null, null, null]);
	        SendErrorRequestDate();
	    }
    } else {
        node.send([null, null, msg, null, null, null]);

        // #5261:TSHPlusにおけるデータのジャーナル反映について.
        SendErrorRequestDate();
    }
} else if (stat === 'success') {
    if (request === false) {
        node.send([msg, null, null, null, null, null]);
        return;
    } else {
        var data = msg.requestData;
        // データOK？
        if (socketlib.checkValidation(socketType, data, 1, 'type')) {
            // 再送要求？
            if (socketlib.isRetry(socketType, data)) {
                if (retryCount < retryMax) {
                    ++retryCount;
                    msg.retryCount = retryCount;
                    node.send([null, null, null, null, null, msg]);
                    return;
                }
                setStatus('timeout', 'IFEdge:TSH リトライ最大回数[' + retryCount + ']に達しました.');
                node.send([null, null, msg, null, null, null]);

                // #5261:TSHPlusにおけるデータのジャーナル反映について.
                SendErrorRequestDate();
                return;
            }
            // 異常データ
            if (socketlib.isAbnormalData(socketType, data)) {
                setStatus('timeout', 'IFEdge:TSH 異常応答電文.');
                node.send([null, msg, null, null, null, null]);

                // #5261:TSHPlusにおけるデータのジャーナル反映について.
                SendErrorRequestDate();
                return;
            }
            // スキップ
            if (socketlib.isSkip(socketType, data)){
                setStatus('skip', 'IFEdge:TSH スキップ応答電文.');
                node.send([null, null, null, null, msg, null]);

                // #5261:TSHPlusにおけるデータのジャーナル反映について.
                SendErrorRequestDate();
                return;
            }

            if (request) {
                // コンソールに表示
                node.log('=========>Received message [' + commonLib.decodeBuffer(data, 'shift-jis').replace(/\r/g, ' ') + ']');

                msg.payload = data;
                msg.datatype = dataType;
                setStatus('success', 'ok');
                node.send([null, null, null, msg, null, null]);
            }
            setStatus('success', 'ok');
            node.send([msg, null, null, null, null, null]);
        } else {
            // ここはエラーリターン
            setStatus('error','IFEdge:TSH 電文長不正.');
            node.send([null, msg, null, null, null, null]);

            // #5261:TSHPlusにおけるデータのジャーナル反映について.
            SendErrorRequestDate();
        }
    }
}

return;

