/**
 * 仕様: 電文長 00810 セット / CRは 810文字目
 */

//入力の形を吸収する
let targetMsg = Array.isArray(msg) ? msg[0] : msg;

//データ源を特定
let dataSrc = targetMsg.messageInfo || targetMsg.payload || targetMsg;

let records = [];
let dumpStr = "";

// dump取得
if (Buffer.isBuffer(dataSrc?.data?.dump)) {
  dumpStr = dataSrc.data.dump.toString();
}
else if (typeof dataSrc?.data?.dump === "string") {
  dumpStr = Buffer.from(dataSrc.data.dump, "hex").toString();
}

// 0D(CR)で分割
if (dumpStr.length > 0) {
  // ★ここを split(/\r/) にしつつ、ログで中身を詳しく見ます
  records = dumpStr.split(/\r/).filter(r => r.length > 0);
}

// ★検討違いを防ぐための重要ログ 3選
node.log(">>> [検証1] 分割後の件数: " + records.length);
if (records.length > 0) {
  node.log(">>> [検証2] 1件目の文字数: " + records[0].length);
  node.log(">>> [検証3] 1件目の先頭10文字: [" + records[0].substring(0, 10) + "]");
}

node.log("records.length = " + records.length);
node.log("isBuffer=" + Buffer.isBuffer(dataSrc.dump));
node.log(">>> [電文構成] 処理開始: ターゲットレコード数=" + records.length);

const packets = [];
const recordsPerPacket = 1;
const totalRecords = records.length;

node.log(">>> [CHECK 4] recordsPerPacketの値: " + recordsPerPacket);

const now = new Date();
const dateStr = now.getFullYear().toString() + (now.getMonth() + 1).toString().padStart(2, "0") + now.getDate().toString().padStart(2, "0");
const timeStr = now.getHours().toString().padStart(2, "0") + now.getMinutes().toString().padStart(2, "0") + now.getSeconds().toString().padStart(2, "0");

for (let i = 0; i < totalRecords; i += recordsPerPacket) {
  const chunkIdx = Math.floor(i / recordsPerPacket) + 1;
  const chunk = records.slice(i, i + recordsPerPacket);
  const isLast = (i + chunk.length >= totalRecords);

  const buf = Buffer.alloc(810, 0x20);
  const record = chunk[0] ? chunk[0].toString() : "";
  // Header
  buf.write("00000", 0);
  buf.write("H", 5);
  buf.write("KK", 6);
  buf.write(isLast ? "E" : "C", 8);
  buf.write("H", 9);
  buf.write("E", 10);
  buf.write(dateStr, 11);
  buf.write(timeStr, 19);

  const procCategory = record.slice(0, 2);
  buf.write(procCategory, 41);

  buf.write("00", 43);
  buf.write("00810", 45);

  // 処理情報
  buf.write(record.slice(0, 101), 64);

  // 明細情報
  let meiseiCount = 0;
  for (let n = 0; n < 10; n++) {
    // record 内の明細開始位置 (処理情報 101バイトの後ろから)
    const srcPos = 101 + (n * 64);
    const detailStr = record.substr(srcPos, 64);

    // 空白以外ならカウント
    if (detailStr.trim().length > 0) {
      meiseiCount++;
    }

    // パケット内の書き込み位置 (165, 229, 293...)
    const destOffset = 165 + (n * 64);
    buf.write(detailStr.padEnd(64, " "), destOffset);
  }

  // 明細件数のセット
  const countStr = meiseiCount.toString().padStart(2, "0");
  buf.write(countStr, 163);   

  // 予備 + CR
  buf.write("  ", 805);
  buf.write("\r", 809);

  packets.push(buf);

  node.log("--- [電文構成] パケット生成中: " + chunkIdx + "個目 (isLast=" + isLast + ")");
}

if (packets.length > 0) {
  msg.packets = packets;
  msg.currentIdx = 0;
  msg.payload = packets[0];
  msg.dataCount = packets.length;
} else {
  node.error("電文データ(messageInfo)が空のため、パケットを生成できませんでした。");
  return null;
}

node.log("<<< [電文構成] 処理終了: 合計パケット数=" + msg.dataCount);

return msg;

