node.warn(`>>> [TCP送信] START: host[${host}] port[${port}] ctl_no[${msgInfo.journalInfo.ctl_no}]`);
node.warn("socketType=" + socketType);

var request = msgInfo.protocolInfo.sendType === 'request' ? true : false;
var dataType = msgInfo.journalInfo.coop_cd;

// 既存の通信ノード内
let packets = msg.packets;
let currentIdx = msg.currentIdx || 0;
let sendData = msg.payload;
msg.sendData = sendData;

node.warn(`DEBUG: currentIdx=${currentIdx}, dataCount=${msg.dataCount}`);

// 制御はこちら
var ballInCourt = true;

// mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 start
