const client = net.createConnection({ host: host, port: port }, () => {
    node.warn("★const client");
    // mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 start
    ConnectionSucc = true;

    node.log(`--- [TCP送信] 接続成功(Socket確立): ${host}:${port}`);

    let stopIndex = (global.get('stopCoopList')).indexOf(checkCoopCd);
    if (stopIndex !== -1) {
        // 接続成功、配信停止の電文種別がありの場合、削除する
        (global.get('stopCoopList')).splice(stopIndex, 1);
    }
    // mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 end
