client.on("connect", function () {
    node.warn("★client.on.connect");

    node.log(`--- [TCP送信] connectイベント発生: データ送信開始 (${sendData.length} bytes)`);

    client.setTimeout(timeout * 1);
    client.write(sendData);
    ballInCourt = false;

    // #5293:[送信時：再送信時の動きについて]
    // Save Send Data
    msg.scoketData = sendData;
    msg.socketFalg = 'Cli_Snd_Idx_' + currentIdx +'_RetryCount_' + msg.currRetryCount + '_ReconnectCount_' + msg.currRetryTime;
    node.send([null, null, null, msg]);
});


var ALL_data;
var ALL_length = -1;
var currentData;

client.on("data", function (data) {
    node.warn("★client.on.data 受信イベント発生");

    node.log(`--- [TCP送信] data受信: ${data.length} bytes 受信`);

    // パケットの蓄積（分割受信への鉄壁の対応）
    if (ALL_length == -1) {
        ALL_length = socketlib.getLength(socketType, data);
        ALL_data = data;
    } else {
        ALL_data = Buffer.concat([ALL_data, data]);
    }

    // 指定の長さ（810バイト等）に達するまで待機
    if (ALL_length !== 0 && ALL_data.length < ALL_length) {
        node.warn(`…受信中 [${ALL_data.length} / ${ALL_length}]`);

        node.log(`--- [TCP送信] 受信継続中: ${ALL_data.length}/${ALL_length}`);

        return;
    }

    // --- 810バイト溜まった「完成電文」の解析開始 ---

    node.log("<<< [TCP送信] 電文受信完了: 解析を開始します");

    let completeMsg = ALL_data;

    // ★受信電文確認ログ
    node.warn(`受信 length=${completeMsg.length}`);
    node.warn(`受信 HEX=${completeMsg.toString('hex').match(/.{1,2}/g).join(' ')}`);
    //node.warn(`受信 ASCII=${completeMsg.toString()}`);

    let resultStatus = completeMsg.slice(43, 45).toString(); // 43-44バイト目の結果通知コード

    // 判定
    var isRetry = socketlib.isRetry(socketType, completeMsg);
    var isSkip = socketlib.isSkip(socketType, completeMsg);
    var isAbnormalData = socketlib.isAbnormalData(socketType, completeMsg);

    // 証拠ログ出力
    msg.scoketData = completeMsg;
    //msg.socketFalg = `Cli_Rev_Status_${resultStatus}_Idx_${currentIdx}`;
    msg.socketFalg = 'Cli_Rev_Idx_' + currentIdx  + '_Status_' + resultStatus  + '_RetryCount_' + msg.currRetryCount + '_ReconnectCount_' + msg.currRetryTime;

    node.send([null, null, null, msg]);

    node.warn(`★解析結果 [Status:${resultStatus}] [Retry:${isRetry}] [Skip:${isSkip}] [Abnormal:${isAbnormalData}]`);

    // --- 分岐ロジック：優先順位と整合性の確保 ---

    // 【再送要求】
    if (isRetry) {
        node.error(`★★応答電文(${resultStatus})：再送信を試行します。`);
        // リトライ回数のカウントアップ
        msg.currRetryCount = (msg.currRetryCount || 0) + 1;

        if (msg.currRetryCount > retryMax) {
            // --- 制限回数を超えた場合の処理 ---
            node.error(`★★★ 再送要求リミット超過 (${msg.currRetryCount}回) ★★★ 送信を断念し、エラー終了します。`);

            ALL_data = null;
            ALL_length = -1;
            ballInCourt = true;

            client.destroy(); // 強制切断
            setStatus('error', `再送要求回数オーバー(${retryMax}回).`);
            node.send([null, msg, null, null]);
            return;
        }

        node.warn(`★再送要求(${msg.currRetryCount}/${retryMax}回目)：同じパケット[Idx:${currentIdx}]を投げ直します。`);        
        ALL_data = null;
        ALL_length = -1;

        client.write(sendData);
        ballInCourt = false; // 相手の返事待ちへ

        // 再送した証拠ログ
        msg.socketFalg = 'Cli_Snd_Idx_' + currentIdx +'_RetryCount_' + msg.currRetryCount  + '_ReconnectCount_' + msg.currRetryTime;
        node.send([null, null, null, msg]);

        return;
    }

    // 【データスキップ】
    if (isSkip) { 
        node.error(`★★応答電文(${resultStatus})：送信を強制中断します。`);
        ALL_data = null;
        ALL_length = -1;
        ballInCourt = true;
        client.end();
        //createRequestResponse["disconnect"]();
        //startDisconnectAckTimer();
        setStatus('error', '応答電文：スキップ.');
        node.send([null, msg, null, null]);
        return;
    }

    // 【データ異常】
    if (isAbnormalData) {
        node.error(`★★応答電文(${resultStatus})：送信を強制中断します。`);
        ALL_data = null;
        ALL_length = -1;
        ballInCourt = true;
        client.end();
        //createRequestResponse["disconnect"]();
        //startDisconnectAckTimer();
        setStatus('error', '応答電文：ダウン.');
        node.send([null, msg, null, null]);
        return;
    }

    // 【正常応答)】
    if (resultStatus === "OK") {
        node.warn(`★正常応答(OK)：パケット[${currentIdx + 1}] 完了。`);

        // お掃除して次へ
        ALL_data = null;
        ALL_length = -1;
        ballInCourt = false;

        if (currentIdx + 1 < msg.dataCount) {
            currentIdx++;
            sendData = packets[currentIdx];
            // 次のパケットを送信
            node.warn(`★次パケット[${currentIdx + 1} / ${msg.dataCount}] を送信。`);
            client.write(sendData);

            // 送信済みログ
            msg.currentIdx = currentIdx;
            msg.scoketData = sendData;
            msg.socketFalg = 'Cli_Snd_Idx_' + currentIdx +'_RetryCount_' + msg.currRetryCount + '_ReconnectCount_' + msg.currRetryTime;
            node.send([null, null, null, msg]);
        } else {
            // 全パケット送信完了
            node.warn("★すべてのパケット送信が正常に完了しました。");
            node.log("<<< [TCP送信] 全パケット完了: 正常終了");
            //createRequestResponse["ack"]();
            //createRequestResponse["disconnect"]();
            //startDisconnectAckTimer();
            client.end();
            setStatus('normal', 'normal');
            msg.requestData = completeMsg;
            node.send([msg, null, null, null]);
        }
    }else{
        node.error(`★★応答電文(${resultStatus})：送信を強制中断します。`);
        ALL_data = null;
        ALL_length = -1;
        ballInCourt = true;
        client.end();
        //createRequestResponse["disconnect"]();
        //startDisconnectAckTimer();
        setStatus('error', '応答電文：不明.');
        node.send([null, msg, null, null]);     
    }
});

