    node.warn("★timeoutnow");

    node.log(`!!! [TCP送信] TIMEOUT発生: 相手からの応答がありません (${timeout / 1000}秒)`);

    if (ALL_data && ALL_data.length > 0) {
        msg.scoketData = ALL_data;
        msg.socketFalg = 'Cli_Rev_Timeout_Idx_' + currentIdx  + '_RetryCount_' + msg.currRetryCount + '_ReconnectCount_' + msg.currRetryTime;
        node.send([null, null, null, msg]);
    }

    client.destroy();
    setStatus('timeout', 'IFEdge:応答電文のタイムアウト.時間[' + timeout / 1000 + ']秒.');
    node.send([null, null, msg, null]);
});

