function setStatus(stat, message) {
    msg.N_status = stat;
    msg.N_message = message;
}

var fs = global.get('fs');
var commonLib = global.get('commonLib');
var setting = commonLib.getSettings();
var path = global.get('path');

/**
 * 複数ファイルかどうかを判定する関数です。
 * @param {*} msg 
 * @returns 
 */
function isMultipleFile(msg) {
    return msg.multiResults && msg.multiResults.length > 1;
}

/**
 * 単一ファイルの処理を行う関数です。
 * @param {*} msg 
 * @returns 
 */
function processingSingleFile(msg) {
    var filename = path.basename(msg.filename);

    var fromPath = path.dirname(msg.filename)
    var extName = path.extname(filename);
    var fileNameStartPart = filename.slice(0, (filename.length - extName.length));

    var delFilePath = msg.filename;
    try {
        var destPath = setting.send.keepDirRoot + '/' + msg.payloadSend.journalInfo.coop_cd + '/';
        if (msg.N_status === 'success') {
            destPath += 'OK/';
        }
        else {
            destPath += 'NG/';
        }

        var dateStr = msg.payloadSend.journalInfo.in_reg_date.substring(0, 10);
        var sendDate = dateStr.replaceAll("-", "");
        destPath += sendDate + '/';
        commonLib.createDirectory(destPath);

        var toPath = destPath;
        destPath += filename;

        fs.copyFileSync(delFilePath, destPath);
        msg.logMessage = 'file copy success [' + delFilePath + '] => [' + destPath + ']';
        node.log(msg.logMessage);
        if (msg.payloadSend.protocolInfo.delete === undefined || msg.payloadSend.protocolInfo.delete === "true") {
            fs.unlinkSync(delFilePath);
            node.log('file [' + delFilePath + '] deleted');
            msg.logMessage = 'file move success [' + delFilePath + '] => [' + destPath + ']';
        }

        // 指定されたパスの下で固定文字列の先頭のファイルを指定のパスに移動します。
        commonLib.MoveFilesFromPathByStartsWith(fromPath, fileNameStartPart, toPath, msg.payloadSend.protocolInfo.delete);
    } catch (error) {
        msg.N_status = 'error';
        msg.N_message = error.message;

        throw error;
    }

    return msg;
}

/**
 * 複数ファイルの処理を行う関数です。
 * msg.multiResults の各メッセージに対して単一ファイル処理を実行します。
 * @param {*} msg 
 * @returns msg（multiResultsの各msgが処理済みとなったもの）
 */
function processingMultipleFiles(msg) {
    const processedResults = [];

    for (const singleMsg of msg.multiResults) {
        try {
            const result = processingSingleFile(singleMsg);
            processedResults.push(result);
        } catch (error) {
            node.error(`ファイル処理中にエラーが発生しました: ${error.message}`, singleMsg);
            processedResults.push(singleMsg);
            msg.multiResults = processedResults;
            msg.loglevel = "error";
            msg.N_status = "init";
            msg.N_message = `ファイル送信処理に失敗しました: [${singleMsg.orgFilename}]`;
            return msg; // エラーが発生した場合はここで終了
        }
    }

    msg.multiResults = processedResults;
    return msg;
}

let resultMsg = isMultipleFile(msg) ? processingMultipleFiles(msg) : processingSingleFile(msg);
node.log(`resultMsg <=: ${JSON.stringify(resultMsg)}`);

return resultMsg;

var commonLib = global.get('commonLib');
var fs = global.get('fs');
var path = global.get('path');
var setting = commonLib.getSettings();


/**
 * 
 * @returns {boolean} true:複数ファイル false:単一ファイル
 */
function isMultipleFile(msg) {
    if (!msg.payload.data.filename) {
        // ファイル名がない場合は単一ファイルとみなす
        return false;
    }
    const fileNameDelimiter = msg.payload.protocolInfo.fileNameDelimiter || '|';
    return msg.payload.data.filename.split(fileNameDelimiter).length > 1;
}

/**
 * 単一ファイルの処理を行う関数です。  
 */
function processingFile(msg) {
    // CTL_NOを取得する
    var ctlNo = msg.payload.journalInfo.ctl_no;

    // 連携版番号
    msg.coop_version = '';
    if (msg.payload.journalInfo.coop_version !== undefined) {
        msg.coop_version = msg.payload.journalInfo.coop_version;
    }

    var orgFilename = '';
    var fileName = setting.tmpDirPath + '/';
    if (msg.payload.data.filename !== undefined &&
        msg.payload.data.filename !== null) {
        // ファイル名の保持
        orgFilename = msg.payload.data.filename;
        // 一意を担保するため yyyyMMddHHmmssSSS_ファイル名 とする
        fileName += commonLib.getTempUniqueKey() + '_' + orgFilename;
    }
    else {
        // yyyyMMddHHmmssSSS_[電文種別]_[通信形式].dmp
        orgFilename = commonLib.createTempFileName((msg.payload.journalInfo.coop_cd), msg.payload.protocolInfo.protocol);
        fileName += orgFilename;
    }

    // #5266:レポート再送信時の送信済みファイル取得方法について
    var buf = '';
    // リトライ場合、送信済みファイルを再取得する
    // リトライデータの場合
    // リトライデータのDUMPが無しの場合
    // リトライデータのファイル名が有りの場合 
    if (
        (msg.payload.data.dump === undefined || msg.payload.data.dump === null || msg.payload.data.dump === '')
        && (msg.payload.data.filename !== undefined && msg.payload.data.filename !== null && msg.payload.data.filename !== '')) {
        // 済みデータを取得する
        // pathから、filesを取得する
        var okFilePath = setting.send.keepDirRoot + '/' + msg.payloadSend.journalInfo.coop_cd + '/OK/';
        var out_reg_date = msg.payload.journalInfo.out_reg_date;

        if (out_reg_date === undefined || out_reg_date === null || out_reg_date === '') {
            msg.N_status = 'internal error';
            msg.N_message = msg.payload.data.filename + 'を保持していません';
            node.log(msg.N_message)
            return [null, msg];
        }
        var dateStr = msg.payload.journalInfo.out_reg_date.substring(0, 10);

        var sendDate = dateStr.replaceAll("-", "")
        okFilePath += sendDate + '/';
        node.log('7175_send_okFilePath:' + okFilePath);
        // パス存在の検証の追加
        if (commonLib.isExist(okFilePath) === true) {
            const okFiles = fs.readdirSync(okFilePath);
            // ファイル ループ
            for (var file of okFiles) {
                let states = fs.statSync((okFilePath + file));
                if (states !== null && states.size !== 0) {
                    let compFile = file.slice(-orgFilename.length);
                    if (compFile === orgFilename) {
                        fs.copyFileSync(okFilePath + file, fileName);
                        buf = 'retry.';
                        msg.logMessage = 'retry file copy success [' + (okFilePath + file) + '] => [' + fileName + ']';
                        node.log(msg.logMessage);
                        break;
                    }
                }
            }
        }

        if (buf === '') {
            var ngFilePath = setting.send.keepDirRoot + '/' + msg.payloadSend.journalInfo.coop_cd + '/NG/';
            ngFilePath += sendDate + '/';
            // パス存在の検証の追加
            if (commonLib.isExist(ngFilePath) === true) {
                var ngFiles = fs.readdirSync(ngFilePath);
                for (var nfile of ngFiles) {
                    let states = fs.statSync((ngFilePath + nfile));
                    if (states !== null && states.size !== 0) {
                        let compFile = nfile.slice(-orgFilename.length);
                        if (compFile === orgFilename) {
                            fs.copyFileSync(ngFilePath + nfile, fileName);
                            buf = 'retry.';
                            msg.logMessage = 'retry file copy success [' + (ngFilePath + nfile) + '] => [' + fileName + ']';
                            node.log(msg.logMessage);
                            break;
                        }
                    }
                }
            }
        }
        if (buf === '') {
            msg.N_status = 'internal error';
            msg.N_message = 'リトライ場合、パス[' + okFilePath + ']にファイル[' + orgFilename + ']が無し。';
            node.log(msg.N_message)
            return [null, msg];
        }
    } else {
        // dump がなければ空のファイルを作成
        var hex = msg.payload.data.dump;
        //    var buf = '';
        if (hex !== undefined && hex !== null) {
            buf = Buffer.from(hex, 'hex');
        }
        fs.writeFileSync(fileName, buf);
    }

    // オリジナルファイル名
    msg.orgFilename = orgFilename;
    // 一時的に作成したファイル
    msg.filename = fileName;
    msg.logMessage = 'file [' + fileName + '] created.';

    node.log(msg.logMessage)
    if (buf === undefined || buf === null) {
        msg.N_status = 'internal error';
        msg.N_message = 'dump is undefined in response' + ' (empty file [' + fileName + '] created)';
        node.log(msg.N_message)
        return [null, msg];
    }

    return [msg, null];
}

/**
 * 複数ファイルの処理を行う関数です。
 * dump内の `fileSplitDelimiterFormat` で区切られたバイナリを分割し、それぞれ単一ファイル処理に渡す。
 */
function processingMultipleFile(msg) {
    const originalFilename = msg.payload.data.filename;
    const originalDump = msg.payload.data.dump;

    // ファイル分割の定義（例："----- %s -----"）
    const format = msg.payload.protocolInfo.fileSplitDelimiterFormat || "----- %s -----";
    msg.multiResults = [];

    // dump全体をバイナリ→文字列へ変換
    const buffer = Buffer.from(originalDump, 'hex');
    const text = buffer.toString('binary');

    // 区切り文字列にマッチする正規表現を構築
    const escapedFormat = format.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const pattern = escapedFormat.replace('%s', '(.+?)');
    const regex = new RegExp(pattern + '\\r?\\n', 'g');

    const matches = [];
    let match;

    // 区切りごとに分割ポイントを特定
    while ((match = regex.exec(text)) !== null) {
        matches.push({
            filename: match[1],                // ファイル名
            startIndex: regex.lastIndex,      // 内容の開始位置
            delimiterLength: match[0].length  // 区切り文字の長さ
        });
    }

    // 各ファイルごとに分割・処理
    msg.logMessage = msg.logMessage || '';
    for (let i = 0; i < matches.length; i++) {
        const { filename, startIndex, delimiterLength } = matches[i];
        const endIndex = (i + 1 < matches.length)
            ? matches[i + 1].startIndex - matches[i + 1].delimiterLength
            : text.length;

        const fileContent = text.slice(startIndex, endIndex);

        let dumpHex;
        let isEmpty = false;

        // 内容が空の場合：ダミー1バイト（00）をセットして後で上書き対応
        if (!fileContent || fileContent.trim() === '') {
            dumpHex = '00';
            isEmpty = true;
        } else {
            dumpHex = Buffer.from(fileContent, 'binary').toString('hex');
        }

        // 単一ファイル処理用にメッセージを複製
        const singleMsg = JSON.parse(JSON.stringify(msg));
        delete singleMsg.multiResults;
        singleMsg.payload.data.filename = path.basename(filename);
        singleMsg.payload.data.dump = dumpHex;
        singleMsg.payload.data.dirPath = path.dirname(filename);
        msg.logMessage += (msg.logMessage ? '\n' : '') + [
            `Processing file: ${singleMsg.payload.data.filename}`,
            `Directory path: ${singleMsg.payload.data.dirPath}`,
            `File content length: ${fileContent.length} bytes`
        ].join('\n');

        // 処理実行
        const [resultMsg, errorMsg] = processingFile(singleMsg);
        if (errorMsg) {
            node.error(`ファイル [${filename}] の処理に失敗しました`, errorMsg);
            return [null, errorMsg];
        }

        // dumpが空だった場合は、後から0バイトで上書きする
        if (isEmpty && resultMsg && resultMsg.filename) {
            try {
                fs.writeFileSync(resultMsg.filename, '');  // 0バイトで上書き
                node.log(`空ファイルとして再作成: ${resultMsg.filename}`);
            } catch (e) {
                node.error(`0バイトファイルへの再書き込み失敗: ${resultMsg.filename}`, e);
                return [null, { N_status: 'error', N_message: '0バイトファイル再作成に失敗' }];
            }
        }

        // 結果を蓄積
        msg.multiResults.push(resultMsg);
    }

    // 元のdumpとファイル名を戻す
    msg.payload.data.filename = originalFilename;
    msg.payload.data.dump = originalDump;
    return [msg, null];
}

/**
 * 単一ファイルの処理を行う関数です。
 * @param {*} msg 
 * @returns 
 */
function processingSingleFile(msg) {
    const singleMsg = JSON.parse(JSON.stringify(msg));
    const originalFilename = msg.payload.data.filename;
    if (msg.payload.data.filename) {
        singleMsg.payload.data.filename = path.basename(originalFilename);
        singleMsg.payload.data.dirPath = path.dirname(originalFilename);
    }

    // 処理実行
    const [resultMsg, errorMsg] = processingFile(singleMsg);
    if (errorMsg) {
        node.error(`ファイル [${originalFilename}] の処理に失敗しました`, errorMsg);
        return [null, errorMsg];
    }

    return [resultMsg, null];
}



