                    retryCount = 0;
                    isTimeoutCheck = false;
                    return;
                }
                let response = socketlib.createResponseRetry(socketType, data);
                connection.write(response);

                connection.Status = 'NG';
                connection.N_datacount = 0;
                connection.ALL_length = -1;

                // Save Send NG Data
                msg.filename = connection.filename;
                msg.scoketData = response;
                msg.socketFalg = 'S_S_NG_' + messageCount;
                node.send([null, msg]);

                // データ出力(NG)
                if (connection.N_data !== undefined && connection.N_data !== null && connection.N_data.length > 0) {
                    msg.payload = connection.N_data;
                    msg.coop_result = 'E2';
                    msg.E2logMessage = 'Socket:受信データ長が不正です.電文[' + commonLib.decodeBuffer(data, 'shift-jis').replace(/\r/g, ' ') + ']';
                    node.send([msg, null]);
                }
                return;
            }
        }
            , timeout);
    }
    if (connection.ALL_data.length < connection.ALL_length) {
        return;
    }
    if (connection.ALL_length === -1) {
        const successHeaderLength = socketlib.getHeaderLengthByIncluded(socketType, true);
        const successAllDataLength = connection.ALL_length + successHeaderLength;
        // add FNSI7302-ini_dial連携で異常な電文を受信しても正常応答（OK）する 周 start
        if ('ini_dial' === msg.datatype && connection.ALL_data.length !== successAllDataLength) {
            return;
        }
    }

    // add FNSI7302-ini_dial連携で異常な電文を受信しても正常応答（OK）する 周 end
    // dataにデータを再設定する
    data = Buffer.alloc(connection.ALL_data.length);
    connection.ALL_data.copy(data, 0, 0, connection.ALL_data.length);
    // コンソールに表示
    node.log('Received message [' + commonLib.decodeBuffer(data, 'shift-jis').replace(/\r/g, ' ') + ']');

    var messageCount = socketlib.getMessageCount(socketType, data);

    if (socketlib.isFirst(socketType, data)) {
        connection.N_datacount === 0;
        inProcess = true;
    }

    // Save Received Data
    msg.filename = connection.filename;
    msg.scoketData = data;
    msg.socketFalg = 'S_R_' + messageCount;
    msg.rcvData = revData;
    node.send([null, msg]);

    // 妥当性チェック
    if (!socketlib.checkValidation(socketType, data, messageCount, msg.datatype)) {
        return;
    }
    //console.log('●●●checkValidation : true .');

    // タイマーをリセット
    clearTimeout(timer);
    retryCount = 0;
    isTimeoutCheck = false;

    // add FNSI7302-ini_dial連携で異常な電文を受信しても正常応答（OK）する 周 start
    // mod FNSI8035-ini_dial連携で電文を受信するとnode-redで例外が発生しini_dial連携ができない 周 start
    //if('ini_dial' === msg.datatype) {
    if ('ini_dial' === msg.datatype && coopLayoutInfo && '' !== coopLayoutInfo) {
        // mod FNSI8035-ini_dial連携で電文を受信するとnode-redで例外が発生しini_dial連携ができない 周 end
        let dataForCheck = commonLib.decodeBuffer(revData, 'shift-jis').replace(/\r/g, ' ');
        node.warn('dataForCheck:' + JSON.stringify(dataForCheck));
        var startIdx = 0;
        for (var mstItem of coopLayoutInfo) {
            //node.log('startIdx(' + startIdx +'), len(' + mstItem.len + ")");

            if (false === mstItem.chkTarget) {
                //node.log('NOT check ' + mstItem.name + ':master item(' + JSON.stringify(mstItem) + '), receive item(' + dataItem + ')');
                startIdx += mstItem.len;
                continue;
            }

            //var dataItem = dataForCheck.slice(startIdx, startIdx+mstItem.len);
            var dataItem = commonLib.decodeBuffer(revData.slice(startIdx, startIdx + mstItem.len), 'shift-jis').replace(/\r/g, ' ');

            //node.log('check ' + mstItem.name + ':master item(' + JSON.stringify(mstItem) + '), receive item(' + dataItem + ')');

            if (null !== mstItem.validVal) {
                node.warn("mstItem.validVal:" + mstItem.validVal);
                var isValid = false;
                for (var val of mstItem.validVal) {
                    node.warn("dataItem:" + dataItem + ", val:" + val);
                    if (dataItem === val) {
                        isValid = true;
                        break;
                    }
                }
                node.warn("isValid:" + isValid);
                if (false === isValid) {
                    let checkErrMessage = mstItem.name + 'の値が不正:可能な値(' + JSON.stringify(mstItem.validVal) + "), 受信(" + dataItem + ").";
                    node.log(checkErrMessage);

                    let response = socketlib.createResponse(socketType, data, false);
                    connection.write(response);

                    // add FNSI7302-ini_dial連携で異常な電文を受信しても正常応答（OK）する 周 20220926 start
                    msg.chkDataResult = checkErrMessage;
                    // add FNSI7302-ini_dial連携で異常な電文を受信しても正常応答（OK）する 周 20220926 end

                    msg.filename = connection.filename;
                    msg.scoketData = response;
                    msg.socketFalg = 'S_S_' + mstItem.errorFlg + '_' + messageCount;
                    node.send([null, msg]);

                    //var checkErrMessage = mstItem.name + 'の値が不正:可能な値(' + JSON.stringify(mstItem.validVal) + "), 受信(" + dataItem + ").";
                    msg.payload = response;
                    // mod 2023-03-29 bug #8424 バックアップファイルのOK/NGフォルダへの移動 孫 start
                    //msg.coop_result = 'S';
                    msg.coop_result = 'E2';
                    // mod 2023-03-29 bug #8424 バックアップファイルのOK/NGフォルダへの移動 孫 end
                    msg.E2logMessage = checkErrMessage;
                    node.send([msg, null]);

                    return;
                }
            } else {
                if ('' === dataItem.replaceAll(' ', '')) {
                    let checkErrMessage = mstItem.name + 'の値が必須ですが、受信電文に値が空.';
                    node.log(checkErrMessage);

                    let response = socketlib.createResponse(socketType, data, false);
                    connection.write(response);

                    // add FNSI7302-ini_dial連携で異常な電文を受信しても正常応答（OK）する 周 20220926 start
                    msg.chkDataResult = checkErrMessage;
                    // add FNSI7302-ini_dial連携で異常な電文を受信しても正常応答（OK）する 周 20220926 end

                    msg.filename = connection.filename;
                    msg.scoketData = response;
                    msg.socketFalg = 'S_S_' + mstItem.errorFlg + '_' + messageCount;
                    node.send([null, msg]);

                    //checkErrMessage = mstItem.name + 'の値が必須ですが、受信電文に値が空.';
                    msg.payload = response;
                    // mod 2023-03-29 bug #8424 バックアップファイルのOK/NGフォルダへの移動 孫 start
                    //msg.coop_result = 'S';
                    msg.coop_result = 'E2';
                    // mod 2023-03-29 bug #8424 バックアップファイルのOK/NGフォルダへの移動 孫 end
                    msg.E2logMessage = checkErrMessage;
                    node.send([msg, null]);

                    return;
                }
            }

            startIdx += mstItem.len;
        }
    }
    // add FNSI7302-ini_dial連携で異常な電文を受信しても正常応答（OK）する 周 end

    // 複数レコードも見据えてデータ結合
    if (connection.N_datacount === 0) {
        connection.N_data = data;
    } else {
        connection.N_data = Buffer.concat([connection.N_data, data]);
    }
    connection.N_datacount = messageCount;

    let response = socketlib.createResponse(socketType, data, true);
    connection.write(response);

    // Save Send OK Data
    msg.filename = connection.filename;
    msg.scoketData = response;
    msg.socketFalg = 'S_S_OK_' + messageCount;
    node.send([null, msg]);

    // 複数レコードも見据えてデータ出力
    if (inProcess && socketlib.isEnd(socketType, data)) {
        // データ出力(OK)
        msg.payload = connection.N_data;
        // #5261:TSHPlusにおけるデータのジャーナル反映について.
        msg.coop_result = '9';
        msg.E2logMessage = '';
        node.send([msg, null]);

        connection.Status = 'OK';
        connection.N_datacount = 0;
        connection.ALL_length = -1;
        inProcess = false;
    }
};

