    // 受信動作停止
    if (commonLib.isProcessSkip('r')) {
        node.log('receive.skipあり->Socket受信停止(' + conn.remoteAddress + '):' + JSON.stringify(msg.watchInfo));
        conn.end();
        return;
    }
    // add 2023-04-11 bug #8376 動作制御ファイルによる動作停止状態の判別ができない 孫 end

    // if (Object.keys(connectionPool).length) {
    // if (connectCount > 0) {
    //     conn.write('full');
    //     conn.end();
    //     conn.unref();
    //     delete[conn];
    //     return;
    // }

    // TCPコネクションを管理する
    var id = (1 + Math.random() * 4294967295).toString(16);
    connectionPool[id] = conn;

    // コネクションへの情報追加
    connectionPool[id].N_datacount = 0;
    connectionPool[id].ALL_length = -1;
    connectionPool[id].Status = '-';

    // yyyyMMddHHmmssSSS_[電文種別]_[通信形式].dmp
    // mod  2022-6-17 ソケット接続が切断されないと連携の通信ダンプが残らない 孟堅　strat
    // var filename = setting.tmpDirPath + '/';
    // filename += commonLib.createTempFileName(msg.datatype, msg.watchInfo.protocol);
    // connectionPool[id].filename = filename;
    connectionPool[id].filename = "";
    // mod  2022-6-17 ソケット接続が切断されないと連携の通信ダンプが残らない 孟堅　end

    node.log("New client connection from [" + conn.remoteAddress + "]. id = [ " + id + " ] , port = [ " + port + " ]");

    // データ受信、クライアント切断、エラーに対するハンドラを設定する
    conn.on('data', function (data) {
        //node.log("データ " + data + " を受信しました。");
        onData(connectionPool[id], data);
    });
    conn.on('close', function () {
        delete connectionPool[id];
        --connectCount;
        onClose();
    });
    conn.on('error', function () {
        onError();
        --connectCount;
    });
    ++connectCount;
};

// ノードが終了する時の処理
// （TCPコネクションを解放する。）
var closeConnection = function () {
    for (var c in connectionPool) {
        if (connectionPool.hasOwnProperty(c)) {
            connectionPool[c].end();
            connectionPool[c].unref();
