# **Soket-Wait**
---
TCP通信待機処理


## 入力
`msg.port` - 待機するポート  
`msg['socket-type']` - 各社対応識別  
`msg.watch` - Watch情報

## 出力
`msg.payload` - 受信電文

## ソース
~~~
var net = global.get('net');
var commonLib = global.get('commonLib');

var port = msg.port * 1;
var type = msg.protocoltype;

// ####################
// protocoltypeの入力チェック
// ####################
var _handler = 'socket_' + type;
var handler = global.get(_handler);

var connectionPool = {};
var count = 0;

// データ受信時のハンドラ
var onData = function(connection, data) {
    var messageCount = 0;
    // 対話処理中のフラグ
    var inProcess = false;

    // コンソールに表示
    node.log('Received message [' + commonLib.decodeBuffer(data, 'shift-jis').replace(/\r/g, ' ') + ']');

    if (handler.isFirst(data)) {
        messageCount = handler.getMessageCount();
        inProcess = true;
    }

    // 妥当性チェック
    if (!handler.checkValidation(data, messageCount, msg.datatype)) {
        response = handler.createResponse(data, 'N2');
        connection.write(response);
        return;
    }

    // 複数レコードも見据えてデータ結合
    if (connection.N_datacount === 0) {
        connection.N_data = data;
    } else {
        connection.N_data = Buffer.concat([connection.N_data, data]);
    }

    response = handler.createResponse(data, 'OK');
    connection.write(response);

    // 複数レコードも見据えてデータ出力
    if (inProcess && handler.isEnd(data)) {
        msg.payload = connection.N_data;
        node.send(msg);    

        connection.N_datacount = 0;
        inProcess = false;
    }
};

// クライアントから切断された場合のハンドラ
var onClose = function() {
    // TODO 切断時の処理が必要であれば、ここで定義する。
    //node.log('Client-> server closed connection');
};

// エラーハンドラ
var onError = function() {
    // TODO エラー処理
};

// クライアントから接続要求を受信した場合のハンドラ
var listener = function(conn) {

    if (Object.keys(connectionPool).length) {
        conn.end();
        conn.unref();
        delete[conn];
        return;
    }

    // TCPコネクションを管理する
    var id = (1+Math.random()*4294967295).toString(16);
    connectionPool[id] = conn;

    // コネクションへの情報追加
    connectionPool[id].N_datacount = 0;

    node.log("New client connection from [" + conn.remoteAddress  + "]. id = [ " +  id + " ] , port = [ " + port + " ]");

    // データ受信、クライアント切断、エラーに対するハンドラを設定する
    conn.on('data', function(data) {
        //node.log("データ " + data + " を受信しました。");
        onData(connectionPool[id], data);
    });
    conn.on('close', function() {
        delete connectionPool[id];
        --count;
        onClose();
    });
    conn.on('error', function() {
        onError();
    });
};

// ノードが終了する時の処理
// （TCPコネクションを解放する。）
var closeConnection = function() {
    for (var c in connectionPool) {
        if (connectionPool.hasOwnProperty(c)) {
            connectionPool[c].end();
            connectionPool[c].unref();
        }
    }
}

node.on('close', function() {
    closeConnection();
    server.close();
});

var server = net.createServer(listener);
server.listen(port);
node.log('listening on port [ ' + port + ' ]');

return;

