var onData = function (connection, data) {
    // コンソールに表示
    //node.log('Socket Data Length [' + data.length+ '] Received message [' + commonLib.decodeBuffer(data, 'shift-jis').replace(/\r/g, ' ') + ']');

    // 無効データ受信に対する応答電文は送信しない(受信したデータは破棄する)
    if (connection.N_datacount === -99) {
        return;
    }

    // 受信データのLengthを取得する
    if (connection.ALL_length === -1) {
        connection.ALL_length = commonLib.getTSHDataLength(data, tshformat);
        connection.ALL_data = data;
    } else {
        connection.ALL_data = Buffer.concat([connection.ALL_data, data]);
    }

    // 受信データのLengthをチェックする
    let responseData = null;
    isTimeoutCheck = true;
    //console.log('==========>connection.ALL_data.length  [' + connection.ALL_data.length + '] connection.ALL_length : [' + connection.ALL_length + ']');
        if (connection.ALL_data.length != connection.ALL_length) {
            if (timer !== null) {
                clearTimeout(timer);
            }
            timer = setTimeout(() => {
                if (isTimeoutCheck) {
                    retryHandler.increment();
                    var retryCount = retryHandler.getCount();
                    if (retryCount > retryMax) {
                        //ここに廃棄応答処理
                        responseData = commonLib.setTSHItemByName(tshDefault, tshformat, 'TelegramId', 'SM');
                        responseData = commonLib.setTSHItemByName(responseData, tshformat, 'ContentsCode', 'RE');
                        connection.write(responseData);
                        connection.Status = 'NG';
                        connection.ALL_length = -1;

                        // TSH Socket電文の保管
                        connection.socketSRCnt++;
                        msg.scoketData = responseData;
                        msg.socketFalg = 'S_' + connection.socketSRCnt + '_S_NG';
                        msg.filename = connection.filename;
                        node.send([null, msg]);

                        // #5261:TSHPlusにおけるデータのジャーナル反映について.
                        // データ出力(NG)
                        if (connection.N_data !== undefined && connection.N_data !== null && connection.N_data.length > 0) {
                            msg.payload = Buffer.from(connection.N_data);
                            msg.filename = connection.filename;
                            msg.coop_result = 'E2';
                            msg.E2logMessage = 'Socket:TSH 再送最大回数[' + retryMax + ']に達しました.';
                            node.send([msg, null]);

                            connection.N_data = '';
                        }
                        retryHandler.reset();
                        return;
                    }
                    //ここに再送要求処理
                    responseData = commonLib.setTSHItemByName(tshDefault, tshformat, 'TelegramId', 'SM');
                    responseData = commonLib.setTSHItemByName(responseData, tshformat, 'ContentsCode', 'EC');
                    connection.write(responseData);
                    connection.Status = 'NG';
                    connection.ALL_length = -1;

                    // TSH Socket電文の保管
                    connection.socketSRCnt++;
                    msg.scoketData = responseData;
                    msg.socketFalg = 'S_' + connection.socketSRCnt + '_S_NG';
                    msg.filename = connection.filename;
                    node.send([null, msg]);
                    return;
                }
            }, timeout);
        }
    if (connection.ALL_data.length < connection.ALL_length) {
        //タイマー起動後の待ち
        return;
    }
    // 受信したデータをループ処理します。
    var loopFlag = true;
    while (loopFlag === true) {
        // チェック電文ＩＤを取得する
        var CheckTelegramId = commonLib.getTSHItemByName(connection.ALL_data, tshformat, 'TelegramId');
        // チェック継続フラグを取得する
        var CheckContinuationFlag = commonLib.getTSHItemByName(connection.ALL_data, tshformat, 'ContinuationFlag');

        // (SD かつ最終電文)以外の場合
        if (CheckTelegramId === 'SD' && CheckContinuationFlag == '1') {
            // 複数電文が有りの場合、データを分割する
            if (connection.ALL_data.length > connection.ALL_length) {
                //console.log('---SD Split------------------>' + connection.ALL_data.length+ ' > ' + connection.ALL_length + '-----------------------------');
                // dataにデータを再設定する
                data = commonLib.getDataByLength(connection.ALL_data, 0, connection.ALL_length);
                data_length = connection.ALL_length;
                connection.N_datacount++;

                // そのたデータを保存する
                connection.ALL_data = commonLib.getDataByLength(connection.ALL_data, connection.ALL_length, (connection.ALL_data.length - connection.ALL_length));
                if (connection.ALL_data.length < tshformat.header_length) {
                    connection.ALL_length = tshformat.header_length;
                } else {
                    connection.ALL_length = commonLib.getTSHDataLength(connection.ALL_data, tshformat);
                }
            } else if (connection.ALL_data.length === connection.ALL_length) {
                //console.log('---SD Split------------------>' + connection.ALL_data.length+ ' = ' + connection.ALL_length + '-----------------------------');
                // 複数電文が無しの場合、dataにデータを再設定する
                data = commonLib.getDataByLength(connection.ALL_data, 0, connection.ALL_length);
                data_length = connection.ALL_length;
                connection.N_datacount++;

                connection.ALL_length = -1;
                // ループ終了
                loopFlag = false;
            } else {
                //console.log('---SD Split------------------>' + connection.ALL_data.length+ ' < ' + connection.ALL_length + '-----------------------------');
                // 受信は終了しませんでしたの場合
                // ループ終了
                loopFlag = false;
                break;
            }
        } else {
            //console.log('--------------------->' + connection.ALL_data.length+ ' & ' + connection.ALL_length + '-----------------------------');
            // dataにデータを再設定する
            data = connection.ALL_data;
            data_length = connection.ALL_length;
            connection.N_datacount++;

            connection.ALL_length = -1;
            // ループ終了
            loopFlag = false;
        }

        // コンソールに表示
        node.log('Received message [' + commonLib.decodeBuffer(data, 'shift-jis').replace(/\r/g, ' ') + ']');
        console.log('---------------------> connection.N_datacount =[' + connection.N_datacount + ']-----------------------------');
        // TSH Socket電文の保管
        connection.socketSRCnt++;
        msg.scoketData = data;
        msg.socketFalg = 'S_' + connection.socketSRCnt + '_R';
        msg.filename = connection.filename;
        node.send([null, msg]);

        // データOK？
        if (!commonLib.TSHCheckValidation(data, data_length)) {
            return;
        } else {
            connection.Status = 'OK';

            // 電文ＩＤを取得する
            var TelegramId = commonLib.getTSHItemByName(data, tshformat, 'TelegramId');
            // データSEQを取得する
            var DataSeqSm = commonLib.getTSHItemByName(data, tshformat, 'DataSeqSm');
            if (DataSeqSm !== undefined && DataSeqSm !== null && DataSeqSm !== '') {
                //                msg.DataSeqSm = DataSeqSm*1 +1;
                //                let len = DataSeqSm.length;
                //                let tmpSeq = commonLib.LeftAppend(util.format('%d', msg.DataSeqSm), len, '0');
                let tmpSeq = DataSeqSm;
                tshDefault = commonLib.setTSHItemByName(tshDefault, tshformat, 'DataSeqSm', tmpSeq);
            }
            var DataSeqSd = commonLib.getTSHItemByName(data, tshformat, 'DataSeqSd');
            if (DataSeqSd !== undefined && DataSeqSd !== null && DataSeqSd !== '') {
                //                msg.DataSeqSd = DataSeqSd*1 +1;
                //                let len = DataSeqSd.length;
                //                let tmpSeq = commonLib.LeftAppend(util.format('%d', msg.DataSeqSd), len, '0');
                let tmpSeq = DataSeqSd;
                tshDefault = commonLib.setTSHItemByName(tshDefault, tshformat, 'DataSeqSd', tmpSeq);
            }
            var DataSeq = commonLib.getTSHItemByName(data, tshformat, 'DataSeq');
            if (DataSeq !== undefined && DataSeq !== null && DataSeq !== '') {
                //                msg.DataSeq = DataSeq*1 +1;
                //                let len = DataSeq.length;
                //                let tmpSeq = commonLib.LeftAppend(util.format('%d', msg.DataSeq), len, '0');
                let tmpSeq = DataSeq;
                tshDefault = commonLib.setTSHItemByName(tshDefault, tshformat, 'DataSeq', tmpSeq);
            }
            // 日付を取得する
            tshDefault = commonLib.setTSHItemByName(tshDefault, tshformat, 'Date', sillyDatetime.format(new Date(), 'MMDD'));
            tshDefault = commonLib.setTSHItemByName(tshDefault, tshformat, 'Time', sillyDatetime.format(new Date(), 'HHmmss'));

            // 内容コードを取得する
            var ContentsCode = commonLib.getTSHItemByName(data, tshformat, 'ContentsCode');
            // 継続フラグを取得する
            var ContinuationFlag = commonLib.getTSHItemByName(data, tshformat, 'ContinuationFlag');

            // 4.受信側は受信した送信済みデータSEQの妥当性に関わらず、セッション開始許可電文を返信する。
            if (connection.N_datacount === 1) {
                console.log('--------------------->Service In N_datacount === [' + connection.N_datacount + ']');
                // 妥当性をチェックし
                // 電文ＩＤ=[SM:メッセージ電文]、内容コード=[SS:セッション開始依頼電文]か
                let responseData = '';
                if (TelegramId === 'SM' && ContentsCode === 'SS') {
                    // ES:セッション開始許可電文を返信する
                    responseData = commonLib.setTSHItemByName(tshDefault, tshformat, 'TelegramId', 'SM');
                    responseData = commonLib.setTSHItemByName(responseData, tshformat, 'ContentsCode', 'ES');

                } else {
                    // RE:データ送信エラー電文を返信する
                    responseData = commonLib.setTSHItemByName(tshDefault, tshformat, 'TelegramId', 'SM');
                    responseData = commonLib.setTSHItemByName(responseData, tshformat, 'ContentsCode', 'RE');
                }
                connection.write(responseData);
                // TSH Socket電文の保管
                connection.socketSRCnt++;
                msg.scoketData = responseData;
                msg.socketFalg = 'S_' + connection.socketSRCnt + '_S';
                msg.filename = connection.filename;
                node.send([null, msg]);
                retryHandler.reset();
                return;
            } else if (connection.N_datacount === -1) {
                console.log('--------------------->Service In N_datacount === [' + connection.N_datacount + ']');
                // 10.サーバは自身の内部的な終了処理を行った後、セッション終了許可電文を返信する。
                // 妥当性をチェックし
                // 電文ＩＤ=[SM:メッセージ電文]、内容コード=[SE:セッション終了依頼電文]か
                let responseData = '';
                if (TelegramId === 'SM' && ContentsCode === 'SE') {
                    // CS:セッション終了許可電文を返信する
                    responseData = commonLib.setTSHItemByName(tshDefault, tshformat, 'TelegramId', 'SM');
                    responseData = commonLib.setTSHItemByName(responseData, tshformat, 'ContentsCode', 'CS');
                } else {
                    // RE:データ送信エラー電文を返信する
                    responseData = commonLib.setTSHItemByName(tshDefault, tshformat, 'TelegramId', 'SM');
                    responseData = commonLib.setTSHItemByName(responseData, tshformat, 'ContentsCode', 'RE');
                }
                connection.write(responseData);
                // TSH Socket電文の保管
                connection.socketSRCnt++;
                msg.scoketData = responseData;
                msg.socketFalg = 'S_' + connection.socketSRCnt + '_S';
                msg.filename = connection.filename;
                node.send([null, msg]);

                // -99場合、無効データ(無効データ受信に対する応答電文は送信しない(受信したデータは破棄する))
                connection.N_datacount = -99;

                // データ出力(OK)
                msg.payload = Buffer.from(connection.N_data);
                msg.filename = connection.filename;
                // #5261:TSHPlusにおけるデータのジャーナル反映について.
                msg.coop_result = '9';
                msg.E2logMessage = '';
                node.send([msg, null]);

                connection.N_data = '';
                retryHandler.reset();
                return;
            } else {
                console.log('--------------------->Service In N_datacount === [' + connection.N_datacount + ']');
                // 7.サーバはAPデータ電文を受信し、最終電文を受信した後に、処理結果返信電文にてレスポンスと最終の送信データSEQを受信データSEQとして返す。
                // 電文ＩＤ=[SD:APデータ送信電文]、内容コード=[00:APデータ送信電文]か
                if (TelegramId === 'SD' && ContentsCode === '00') {
                    var colInfo = commonLib.getTSHColInfoByName(data, tshformat, 'Data');
                    var start = colInfo.start;
                    var len = colInfo.len;
                    var requestData = data.slice(start, start + len);
                    if (connection.N_data === undefined || connection.N_data === null || connection.N_data === '') {
                        connection.N_data = requestData;
                    } else {
                        connection.N_data = Buffer.concat([connection.N_data, requestData]);
                    }

                    // 継続フラグ=[0:最終電文]か
                    if (ContinuationFlag === '0') {
                        // SS:APデータ送信成功電文を返信する
                        let responseData = commonLib.setTSHItemByName(tshDefault, tshformat, 'TelegramId', 'SM');
                        responseData = commonLib.setTSHItemByName(responseData, tshformat, 'ContentsCode', 'SS');
                        connection.write(responseData);
                        // TSH Socket電文の保管
                        connection.socketSRCnt++;
                        msg.scoketData = responseData;
                        msg.socketFalg = 'S_' + connection.socketSRCnt + '_S';
                        msg.filename = connection.filename;
                        node.send([null, msg]);

                        connection.N_datacount = -2;
                        retryHandler.reset();
                    }
                    else if (ContinuationFlag !== '1') {
                        // RE:データ送信エラー電文を返信する
                        let responseData = commonLib.setTSHItemByName(tshDefault, tshformat, 'TelegramId', 'SM');
                        responseData = commonLib.setTSHItemByName(responseData, tshformat, 'ContentsCode', 'RE');
                        connection.write(responseData);
                        // TSH Socket電文の保管
                        connection.socketSRCnt++;
                        msg.scoketData = responseData;
                        msg.socketFalg = 'S_' + connection.socketSRCnt + '_S';
                        msg.filename = connection.filename;
                        node.send([null, msg]);

                        // データ出力(NG)
                        if (connection.N_data !== undefined && connection.N_data !== null && connection.N_data.length > 0) {
                            msg.payload = Buffer.from(connection.N_data);
                            msg.filename = connection.filename;
                            msg.coop_result = 'E2';
                            msg.E2logMessage = '受信APデータ電文不正.継続フラグが不正。';
                            node.send([msg, null]);

                            connection.N_data = '';
                        }
                        retryHandler.reset();
                        return;
                    }
                    else{
                        // 継続フラグが1なら待つ
                        return;
                    }
                } else if (TelegramId === 'SM' && ContentsCode === 'SE') {
                    // 電文ＩＤ=[SM:メッセージ電文]、内容コード=[SE:セッション終了依頼電文]か
                    // CS:セッション終了許可電文を返信する
                    let responseData = commonLib.setTSHItemByName(tshDefault, tshformat, 'TelegramId', 'SM');
                    responseData = commonLib.setTSHItemByName(responseData, tshformat, 'ContentsCode', 'CS');
                    connection.write(responseData);
                    // TSH Socket電文の保管
                    connection.socketSRCnt++;
                    msg.scoketData = responseData;
                    msg.socketFalg = 'S_' + connection.socketSRCnt + '_S';
                    msg.filename = connection.filename;
                    node.send([null, msg]);

                    // #5261:TSHPlusにおけるデータのジャーナル反映について.
                    // データ出力(NG)
                    if (connection.N_data !== undefined && connection.N_data !== null && connection.N_data.length > 0) {
                        msg.payload = Buffer.from(connection.N_data);
                        msg.filename = connection.filename;
                        msg.coop_result = 'E2';
                        msg.E2logMessage = '受信APデータ電文不正.電文[' + commonLib.decodeBuffer(data, 'shift-jis').replace(/\r/g, ' ') + ']';
                        node.send([msg, null]);

                        connection.N_data = '';
                    }
                    retryHandler.reset();
                    return;
                } else {
                    // 以外場合
                    // RE:データ送信エラー電文を返信する
                    let responseData = commonLib.setTSHItemByName(tshDefault, tshformat, 'TelegramId', 'SM');
                    responseData = commonLib.setTSHItemByName(responseData, tshformat, 'ContentsCode', 'RE');
                    connection.write(responseData);
                    // TSH Socket電文の保管
                    connection.socketSRCnt++;
                    msg.scoketData = responseData;
                    msg.socketFalg = 'S_' + connection.socketSRCnt + '_S';
                    msg.filename = connection.filename;
                    node.send([null, msg]);

                    // #5261:TSHPlusにおけるデータのジャーナル反映について.
                    // データ出力(NG)
                    if (connection.N_data !== undefined && connection.N_data !== null && connection.N_data.length > 0) {
                        msg.payload = Buffer.from(connection.N_data);
                        msg.filename = connection.filename;
                        msg.coop_result = 'E2';
                        msg.E2logMessage = '受信APデータ電文不正.電文[' + commonLib.decodeBuffer(data, 'shift-jis').replace(/\r/g, ' ') + ']';
                        node.send([msg, null]);

                        connection.N_data = '';
                    }
                    retryHandler.reset();
                    return;
                }
            }
        }
    }
};

