// 2.クライアントがConnectしてコネクションを開設する。
// クライアントから接続要求を受信した場合のハンドラ
var listener = function (conn) {
    // add 2023-04-11 bug #8376 動作制御ファイルによる動作停止状態の判別ができない 孫 start
    // 受信動作停止
    if (commonLib.isProcessSkip('r')) {
        node.log('receive.skipあり->TshSocket受信停止(' + conn.remoteAddress + '):' + JSON.stringify(msg.watchInfo));
        conn.end();
        return;
    }
    // add 2023-04-11 bug #8376 動作制御ファイルによる動作停止状態の判別ができない 孫 end

    // TCPコネクションを管理する
    var id = (1 + Math.random() * 4294967295).toString(16);
    connectionPool[id] = conn;
    connectionPool[id].Status = '-';

    // コネクションへの情報追加
    connectionPool[id].N_datacount = 0;
    connectionPool[id].ALL_length = -1;
    connectionPool[id].socketSRCnt = 0;

    // yyyyMMddHHmmssSSS_[電文種別]_[通信形式].dmp
    var filename = setting.tmpDirPath + '/';
    filename += commonLib.createTempFileName(msg.datatype, msg.watchInfo.protocol);
    connectionPool[id].filename = filename;

    node.log("New client connection from [" + conn.remoteAddress + "]. id = [ " + id + " ] , port = [ " + port + " ]");

    // データ受信、クライアント切断、エラーに対するハンドラを設定する
    conn.on('data', function (data) {
        //node.log("データ " + data + " を受信しました。");
        onData(connectionPool[id], data);
    });
    conn.on('close', function () {
        delete connectionPool[id];
        --connectCount;
        onClose();
    });
    conn.on('error', function () {
        onError();
        --connectCount;
    });
    ++connectCount;
};

// ノードが終了する時の処理
// （TCPコネクションを解放する。）
var closeConnection = function () {
    for (var c in connectionPool) {
        if (connectionPool.hasOwnProperty(c)) {
            connectionPool[c].end();
            connectionPool[c].unref();
        }
    }
}

node.on('close', function () {
    closeConnection();
    server.close();
});

var server = net.createServer(listener);
server.listen(port);
node.log('listening on port [ ' + port + ' ]' + " [ " + msg.datatype + " : " + msg.ope_cd + " ]");

return;

// add 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 start
var util = global.get('util');
// add 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 end

// TSHPlusSocket通信データフォーマットをチェックする
var sillyDatetime = global.get('sillyDatetime');
var commonLib = global.get('commonLib');
var setting = commonLib.getSettings();


var socketType = msg['socket-type'];
var tshformat;
// TSHPlusSocket通信データフォーマットを取得する
var tshformatList = setting.tshplus_telegram_format;
var tshformat_length = tshformatList.length;
for (let k=0; k<tshformat_length; k++) {
    let socketTypeTmp = tshformatList[k]['socket-type'];
    if (socketTypeTmp !== undefined && socketTypeTmp === socketType) {
        tshformat = tshformatList[k];
        break;
    }
}
// check tshformat
if (tshformat === undefined || tshformat === null || tshformat === '') {
    setStatus('error','tshplus_telegram_format undefined. socket-type=[' + socketType + '] ');
    node.send([msg, null]);
    return;
}

var formatCnt = tshformat.format.length;
var all_length = 0;
for (let i=0; i<formatCnt; i++) {
    var format = tshformat.format[i];
    all_length = all_length + format.length;

    // check name undefined
    if (format.name === undefined || format.name.length === 0) {
        setStatus('error','tshplus_format error: format[' + (i+1) + '].name undefined.');
        node.send([msg, null]);
        return;
    }
    // check length undefined
    if (format.length === undefined) {
        setStatus('error','tshplus_format error: format[' + (i+1) + '].length undefined.');
        node.send([msg, null]);
        return;
    }
    // check value undefined
    if (format.value === undefined) {
        setStatus('error','tshplus_format error: format[' + (i+1) + '].value undefined.');
        node.send([msg, null]);
        return;
    }
    // check length = 0 ?
    if (format.name !== 'Data' && format.length === 0) {
        setStatus('error','tshplus_format error: format[' + (i+1) + '].length = 0.');
        node.send([msg, null]);
        return;
    }
    // check value = '' ?
    if (format.name !== 'Data' && format.value.length === 0) {
        setStatus('error','tshplus_format error: format[' + (i+1) + '].value = null.');
        node.send([msg, null]);
        return;
    }
    // check value.length = length ?
    if (format.name !== 'Data') {
        if ((format.value.startsWith('0x') === false && format.value.length !== format.length) 
         || (format.value.startsWith('0x') === true  && format.length !== 1)) {
            setStatus('error','tshplus_format error: format[' + (i+1) + '].value.length <> length.');
            node.send([msg, null]);
            return;
        }
    } else {
        if (format.value.length !== 0 || format.length !== 0) {
            setStatus('error','tshplus_format error: format[' + (i+1) + '].value.length <> length.');
            node.send([msg, null]);
            return;
        }
    }
}

if (all_length !==  tshformat.header_length) {
    setStatus('error','tshplus_format error: total item length (' + all_length + ')<> header_length(' + tshformat.header_length + ').');
    node.send([msg, null]);
    return;
}

// TSHPlusSocket通信データ項目のデフォルト値を設定する
var tshDefault = Buffer.alloc((tshformat.header_length)*1);
var begin = 0;
for (let i=0; i<formatCnt; i++) {
    var format_value = tshformat.format[i].value;
    if (format_value.startsWith('0x') || format_value.startsWith('0X')){
        // 2進数の場合、Unicodeコードを1文字に変換する
        (commonLib.encodeString(String.fromCharCode(commonLib.Str2Hex(format_value)), 'shift-jis')).copy(tshDefault, begin, 0, 1);
        begin = begin + 1;
    } else if (tshformat.format[i].name === 'Data') {
