            mm = mmChange.mm;
            hh = hh + mmChange.hh;
            // 時>24の場合、時を再設定する
            let hhChange = changeHour(hh);
            hh = hhChange.hh;
            //console.log('hh:mm:ss->[' + ("00" + hh).slice(-2) + ':' + ("00" + mm).slice(-2) + ':' + ("00" + ss).slice(-2) + ']');

            // 取込実施時刻範囲を設定する
            if (hhChange.dd === 0) {
                let watchTime = {};
                watchTime.start = startTime + ':00';
                watchTime.end = ('00' + hh).slice(-2) + ':' + ('00' + mm).slice(-2) + ':' + ('00' + ss).slice(-2);
                watchTimes.push(watchTime);
            } else {
                // 時間が当日を超えた場合、取込実施時刻範囲を追加する
                let watchTime = {};
                watchTime.start = startTime + ':00';
                watchTime.end = '24:00:00';
                watchTimes.push(watchTime);

                let watchTimeAdd = {};
                watchTimeAdd.start = '00:00:00';
                watchTimeAdd.end = ('00' + hh).slice(-2) + ':' + ('00' + mm).slice(-2) + ':' + ('00' + ss).slice(-2);
                watchTimes.push(watchTimeAdd);
            }
        });
    }
    node.log('----- watchTimes : ' + JSON.stringify(watchTimes));
}

msg.watchTimes = watchTimes;
msg.watch_model = watch_model;
msg.watch = msg.payload;
console.log('-------------------------setWatchInfo OK End-----------------------------------');

return msg;

function changeHour(time = 0) {
    let times = {};
    times.ss = 0;
    times.mm = 0;
    times.hh = time % 24;
    times.dd = parseInt(time / 24);
    return times;
}

function changeMinute(time = 0) {
    let times = {};
    times.ss = 0;
    times.mm = time % 60;
    times.hh = parseInt(time / 60);
    times.dd = 0;
    return times;
}

function changeSecond(time = 0) {
    let times = {};
    times.ss = time % 60;
    times.mm = parseInt(time / 60) % 60;
    times.hh = parseInt(time / (60 * 60));
    times.dd = 0;
    return times;
}
