(async () => {
    for (; ;) {
        // 0.存在しない例外ファイルに例外Listを削除する
        exceptionMap.forEach(function (value, key) {
            if (false === commonLib.isExist((pollingPath + '/' + key))) {
                exceptionMap.delete(key);
                console.log('======>exceptionMap->[' + (pollingPath + '/' + key) + '] is removed.');
            }
        });

        // 1.ポーリング
        //console.log('======>polling_time=[' + polling_time + ']');
        await sleep(polling_time);

        // 2.ポーリングパスは存在しますか？
