            if (false === commonLib.isExist(pollingPath)) {
                node.log('======>watch_model=[' + watch_model + '] File-Watch:path not exists. [' + pollingPath + ']');
                await sleep(polling_time);
                continue;
            }
        } catch (err) {
            node.log('======>watch_model=[' + watch_model + '] File-Watch:path not exists. [' + pollingPath + ']');
            await sleep(polling_time);
            continue;
        }

        // 3.取込実施時刻範囲をチェックする
        if (is_day !== undefined && is_day !== null && is_day === 'true') {
            let dt = new Date();
            let hh = ("00" + dt.getHours()).slice(-2);
            let mm = ("00" + dt.getMinutes()).slice(-2);
            let ss = ("00" + dt.getSeconds()).slice(-2);
            let nowTime = hh + ':' + mm + ':' + ss;
            let isDay = false;
            //console.log('======>1 nowTime=[' + nowTime + '] isDay=[' + isDay + ']');
            for (let cnt = 0; cnt < watchTimes.length; cnt++) {
                if (nowTime >= watchTimes[cnt].start && nowTime <= watchTimes[cnt].end) {
                    isDay = true;
                    break;
                }
            }
            //console.log('======>2 nowTime=[' + nowTime + '] isDay=[' + isDay + ']');
            if (isDay === false) {
                if (isDayStatus === true) {
                    isDayStatus = false;
                    node.log('-----[' + datatype + ']-[' + coop_version + ']:Watch End   At : [' + nowTime + ']');
                }
                await sleep(polling_time);
                continue;
            }
            //console.log('======>3 nowTime=[' + nowTime + '] isDay=[' + isDay + ']');
            if (isDay === true && isDayStatus === false) {
                isDayStatus = true;
                node.log('-----[' + datatype + ']-[' + coop_version + ']:Watch Start At : [' + nowTime + ']');
            }
        }

        // 4.ポーリングパス下のファイルを取得する
        let files = [];
        try {
            files = fs.readdirSync(pollingPath);
            if (files === null || files.length === 0) {
                await sleep(polling_time);
                continue;
            }
        } catch (err) {
            node.log('======>watch_model=[' + watch_model + '] File-Watch:access error. [' + pollingPath + ']');
            await sleep(polling_time);
            continue;
        }

        // 5.受信動作停止
        if (commonLib.isProcessSkip('r')) {
            node.log('receive.skipあり->File-Watch受信停止:' + JSON.stringify(msg.watchInfo));
            await sleep(polling_time);
            continue;
        }

        // 6.ファイルをループして、対象ファイルかどうかを判断する
        for (let file of files) {
            // 6-1.ファイルステータスを取得し、パスかどうかを判断する
            if (false === commonLib.isExist((pollingPath + '/' + file))) {
                //node.log('======>File-Watch: File not Exist. Path=[' + (pollingPath + '/' + file) + ']');
                continue;
            }
            let stats = fs.statSync((pollingPath + '/' + file));
            if (stats.isDirectory()) {
                //node.log('======>File-Watch:Invalid object. Path=[' + (pollingPath + '/' + file) + ']');
                continue;
            }

            // 6-2.対象ファイルかどうかを判断する
            if (pollingPattern !== '' && pollingPattern !== '*' && file.match(pollingReg) === null) {
                // 対象以外の場合
                //node.log('======>File-Watch:Invalid object. File=[' + (pollingPath + '/' + file) + '] pollingPattern=[' + pollingPattern + ']');
                continue;
            }

            // 6-3.例外ファイルを判断する
            let fileMtime = stats.mtime;
            let year = stats.mtime.getFullYear();
            let month = stats.mtime.getMonth() + 1;
            let day = stats.mtime.getDate();
            let hour = stats.mtime.getHours();
            let minutes = stats.mtime.getMinutes();
            let seconds = stats.mtime.getSeconds();
            let fileMtimeStr = year + ('00' + month).slice(-2) + ('00' + day).slice(-2) + ('00' + hour).slice(-2) + ('00' + minutes).slice(-2) + ('00' + seconds).slice(-2);
            if (exceptionMap.get(file) !== undefined && exceptionMap.get(file) === fileMtimeStr) {
                //console.log('>>>>>>>>>>>>>>>>>>>>>>>>>>>>> exception file=[' + (file + '_' + exceptionMap.get(file)) + ']');
                //console.log(exceptionMap);
                continue;
            }

            // 6-4.File1の場合、電文ファイルに(ポーリングパス+ポーリングファイル)を取得する
            let coopFile = file;
            let coopPath = pollingPath;
