                    coopFile = coopFile.replace(pollingReg, dataPattern);
                }
            }
            console.log('======>Data  CoopPathFile=[' + (coopPath + '/' + coopFile) + ']');

            // 対象の場合
            // 6-6.tmpパス下に電文を保管する
            if (false === commonLib.isExist((coopPath + '/' + coopFile))) {
                node.log('File-Watch:Data File Not exists. File=[' + (coopPath + '/' + coopFile) + ']');
                exceptionMap.set(file, fileMtimeStr);
                continue;
            }
            // [電文種別、タイムスタンプ]を追加する、Temp電文ファイル名を再設定する
            let tempCoopFile = commonLib.getTempUniqueKey() + '_' + datatype + '_' + protocol + '_' + 'R' + '_' + coopFile;
            try {
                fs.copyFileSync((coopPath + '/' + coopFile), (tmpPath + '/' + tempCoopFile));
            } catch (err1) {
                node.log('File-Watch:Polling File Copy NG. File=[' + (coopPath + '/' + coopFile) + ']->[' + (tmpPath + '/' + tempCoopFile) + '] messgae=[' + err1.stack + ']');
                exceptionMap.set(file, fileMtimeStr);
                continue;
            }
            node.log('File-Watch:Polling File Copy success. File=[' + (coopPath + '/' + coopFile) + ']->[' + (tmpPath + '/' + tempCoopFile) + ']');

            // 6-7.To AWS Info
            msg.watchInfo.data = tmpPath;
            msg.payload = (tmpPath + '/' + tempCoopFile);
            msg.filename = tempCoopFile;
            msg.topic = pollingPath;
            msg.loglevel = 'INFO';
            node.send(msg);

            // 8874-複数なNKK検査結果情報を受信する時エラがー発生する 周 add start
            await sleep(interval_ms);
            // 8874-複数なNKK検査結果情報を受信する時エラがー発生する 周 add end

            // 6-8.電文ファイルを削除する
            if (commonLib.isExist((coopPath + '/' + coopFile)) === true) {
                try {
                    fs.unlinkSync((coopPath + '/' + coopFile));
