                    } catch (err2) {
                        node.log('File-Watch:Polling File Delete NG. File=[' + (pollingPath + '/' + file) + '] messgae=[' + err2.stack + ']');
                        exceptionMap.set(file, fileMtimeStr);
                    }
                }
            }

            // 6-10.fileに例外Listを削除する
            if (exceptionMap.get(file) !== undefined) {
                exceptionMap.delete(file);
                console.log('======>exceptionMap->[' + (pollingPath + '/' + file) + '] is removed.');
            }
        }
    }
