            node.send([null, msg]);
        } else {
            // 終了(ERROR)
            let logMsg = '受信電文処理結果取得に成功しました。受信電文変換に失敗しました。変換ステータス(AnaResult)=[' + msg.payload + ']' 
                + ', HTTP Request body = [' + JSON.stringify(msg.sendBody) + ']';
            node.log(logMsg);

            msg.statusCode = 9999;
            msg.loglevel = 'ERROR';
            msg.payload = logMsg;
            node.send([msg, null]);
        }
    } else {
        // HTTP-ERROR
