        logMsg += 'HTTP Response status = [' + msg.statusCode + '] and message = [' + msg.payload + ']';
        node.log(logMsg);

        msg.loglevel = 'ERROR';
        msg.payload = logMsg;
        node.send([msg, null]);
    }
}
return;
