                // 接続成功、配信停止の電文種別がありの場合、削除する
                (global.get('stopCoopList')).splice(stopIndex, 1);
            }
            // mod 2023-04-13 bug #8552 coop_result=R以降の送信処理が行われない 孫 end

            _this.client = client;
            const auth = `<Content-Type>text/xml; charset=utf-8</Content-Type>
                <SOAPAction>http://medical.nec.co.jp/IDataServiceProviderService/Request</SOAPAction>
                <SMAuthenticate></SMAuthenticate>
                <Accept-Encoding></Accept-Encoding>
                <URI>/DataServiceProviderService.svc</URI>`;
            client.addSoapHeader(auth);
            _this.createSoapRequest(client, args);
        })
    },
    // 送信要求は応答データに戻ります。
    createSoapRequest: function (client, args) {
        let _this = this;
        if (client) {
            client.Request(args, function (err, result) {
                if (err !== undefined && err !== null) {
                    if (err.code === 'ESOCKETTIMEDOUT') {
                        _this.retrySoapRequest(client, args)
                            .then(function (data) {
                                if (data === 'Timeout') {
                                    msg.N_status = 'timeout';
                                    msg.N_message = 'IFEdge:connect timeout';
                                    node.send([null, msg, null]);
                                    return;
                                } else {
                                    msg.N_status = 'success';
                                    msg.N_message = 'ok';
                                    msg.N_data = data;
                                    node.send([null, null, msg]);
                                    return;
                                }
                            })
                            .catch(function (data) {
                                if (data === 'NotClient') {
                                    msg.N_status = 'error';
                                    msg.N_message = 'IFEdge:Connect failed [notHasClient]';
                                    node.send([msg, null, null]);
                                    return;
                                } else {
                                    msg.N_status = 'error';
                                    msg.N_message = 'IFEdge:UnKnow error';
                                    node.send([msg, null, null]);
                                    return;
                                }
                            });
                    } else {
                        //タイムアウト以外の要求エラー
                        node.error(err);
                        msg.N_status = 'error';
                        msg.N_message = 'IFEdge:Connect failed [' + err.stack + ']';
                        node.send([msg, null, null]);
                        return;
                    }
                } else {
                    //要求がタイムアウトしていません
                    msg.N_status = 'success';
                    msg.N_message = 'ok';
                    msg.N_data = result;
                    node.send([null, null, msg]);
                    return;
                }
            }, { timeout: _this.timeout });
        } else {
            // SOAPクライアントの作成に失敗しました
            msg.N_status = 'error';
            msg.N_message = 'IFEdge:Connect failed [Client Not Exists]';
            node.send([msg, null, null]);
            return;
        }
    },
    //タイムアウト再接続方法は、PROM ISEの例を返します。
    retrySoapRequest: function (client, args) {
        let _this = this;
        let num = _this.initRetryNum;
        return new Promise(function (resolve, reject) {
            if (client) {
                var time = 0;
                //タイマーを作成
                var retrySoap = setInterval(function () {
                    _this.simpleCreatReq(client, args)
                        .then(function (data) {
                            _this.result = data;
                            clearInterval(retrySoap);
                            resolve(data);
                        })
                        .catch(function (data) {
                            num++;
                            if (num === _this.retry && _this.result === '') {
                                _this.result = 'timeout';
                                clearInterval(retrySoap);
                                resolve('Timeout');
                            }
                        });
                }, _this.timeout)
            } else {
                reject('NotClient');
            }
        })
    },
    //作成要求は、PROM ISEの例に戻る。RESOLVED成功 失敗REJECT
    simpleCreatReq: function (client, args) {
        let _this = this;
        if (client) {
            return new Promise(function (res, rej) {
                client.Request(args, function (err, result) {
                    if (err !== undefined && err !== null) {
                        rej(err);
                    } else {
                        res(result);
                    }
                }, { timeout: _this.timeout })
            })
        }

    }
}
