function deleteBackupPathFile(paraPath, paraFile, paraChkDate) {
    let checkPath = paraPath + paraFile;
    // add 2023-04-17 bug #8361 SSI連携の連携設定にGX連携・NKKK連携で追加された設定が横展開されていない 孫 start
