    let checkStats = fs.statSync(checkPath);
    if (checkStats.isDirectory()) {
        if (paraFile > paraChkDate) {
            node.log(checkPath + '(日付:' + paraFile + ')は削除対象外のため削除しません。');
            return "";
        }
        msg.cmd = makeDeleteDirCmd(checkPath);
    } else {
        let yyyy = checkStats.mtime.getFullYear();
        let mm = checkStats.mtime.getMonth() + 1;
        let dd = checkStats.mtime.getDate()
        let mtimeOrg = yyyy + ("00" + mm).slice(-2) + ("00" + dd).slice(-2);
        if (mtimeOrg > paraChkDate) {
            node.log(checkPath + '(日付:' + mtimeOrg + ')は削除対象外のため削除しません。');
            return "";
        }
        msg.cmd = makeDeleteFileCmd(checkPath);
    }
    logMsg = checkPath + 'を削除しました。';
    node.log(logMsg);
    msg.logMsg = logMsg;
    node.send(msg);
    return msg;
}
