        node.send(msg);
    } catch (e) {
        node.error('内部エラー', msg);
    }
};

// 接続要求をClientから受信したの処理
var listener = function(conn) {

    // TCP接続
    var id = (1+Math.random()*4294967295).toString(16);
    connectionPool[id] = conn;

    node.log("New View client connection from [" + conn.remoteAddress  + "]. id = [ " +  id + " ] , port = [ " + port + " ]");

    // データ受信、クライアント切断、エラー処理
    conn.on('data', function(data) {
        onData(connectionPool[id], data);
    });

    conn.on('close', function() {
        node.log("View Socket Server Close. [" + id +"]");
        delete connectionPool[id];
        --connectCount;
    });

    conn.on('error', function() {
        --connectCount;
    });
    ++connectCount;
};

// ノード終了時、TCP接続を解放する処理
var closeConnection = function() {
    for (var c in connectionPool) {
        if (connectionPool.hasOwnProperty(c)) {
            connectionPool[c].end();
            connectionPool[c].unref();
        }
    }
}

node.on('close', function() {
    closeConnection();
    server.close();
});

var server = net.createServer(listener);
