        node.error('内部エラー', msg);
    }
});

// メッセージ受信
ws.on('message', function (data) {
    try {
        if (timeoutflug) {
            return;
        } else {
            clearTimeout(timeoutId);
            clearTimeout(resetId);
            var response = JSON.parse(data);
            msg.payload = response;
            msg.statusCode = response.status;
            msg.status = response.status;
            if (response.status === 500) {
                msg.loglevel = 'ERROR';
                msg.ErrorCode = '9993';
                msg.ErrorMessage = response.message;
            } else if (response.status === 200) {
                msg.ErrorCode = '0000';
                msg.ErrorMessage = 'OK';
            }
            console.log('staus = ' + msg.payload.status + ','
                + msg.payload.results.length + ' result records received. message : [' + msg.payload.message + ']');
            node.send([msg, null]);
        }
