function isUploadReadyZip(logHead, zipFile) {
    // upload-ready 判定:
    // 1. logHead で始まる
    // 2. 末尾が _00001.zip のような 5 桁連番
    const ruleZip = /_\d{5}\.zip$/;
    return zipFile.startsWith(logHead) && ruleZip.test(zipFile);
}

function createNormalizedZipFileName(logHead, logType, logPath, zipFile) {
    let baseName = path.basename(zipFile, '.zip');
    let zipFileHead = '';

    // nodered/view は既存命名規則を維持する。
    if (logType === 'nodered' && baseName.startsWith('node-red')
        || logType === 'view' && baseName.startsWith('ViewSync')) {
        zipFileHead = logHead + baseName + '_';
    } else {
        let splitName = baseName.split('_');
        // CSI_YYYYMMDD.zip のように 4 要素目がない場合は末尾要素を suffix として使う。
        let suffixName = splitName[3];
        if (suffixName === undefined) {
            suffixName = splitName[splitName.length - 1];
        }
        zipFileHead = logHead + logType + '_' + suffixName + '_';
    }

    for (let seqNo = 1; ; seqNo++) {
        let seqText = ('00000' + seqNo).slice(-5);
        let normalizedZipFile = zipFileHead + seqText + '.zip';
        if (normalizedZipFile === zipFile || commonLib.isExist(logPath + '/' + normalizedZipFile) === false) {
            return normalizedZipFile;
        }
    }
}

